runtimeCallbacks.arguments:
(() =>
        {
            isCollapsed = !isCollapsed;
            if (tTxt != null) tTxt.text = isCollapsed ? "Mở" : "Gọn";
            if (txtQuestTitle != null) txtQuestTitle.gameObject.SetActive(!isCollapsed);
            if (descScrollRect != null) descScrollRect.gameObject.SetActive(!isCollapsed);
            else if (txtQuestReward != null) txtQuestReward.gameObject.SetActive(!isCollapsed);
            if (pBgObj != null) pBgObj.SetActive(!isCollapsed);
            if (btnClaimQuick != null) btnClaimQuick.gameObject.SetActive(!isCollapsed);
            if (btnAchievement != null) btnAchievement.gameObject.SetActive(!isCollapsed);
            if (qRt != null)
            {
                qRt.sizeDelta = isCollapsed ? (wideQuestBar ? new Vector2(64f, 68f) : new Vector2(38f, 38f)) :
                    (originalQuestBarSize.x > 80f ? originalQuestBarSize : new Vector2(260f, 44f));
                if (btRt != null)
                {
                    btRt.anchorMin = isCollapsed ? new Vector2(0.5f, 0.5f) : new Vector2(1f, 0.5f);
                    btRt.anchorMax = isCollapsed ? new Vector2(0.5f, 0.5f) : new Vector2(1f, 0.5f);
                    btRt.pivot = isCollapsed ? new Vector2(0.5f, 0.5f) : new Vector2(1f, 0.5f);
                    btRt.anchoredPosition = isCollapsed ? Vector2.zero : new Vector2(-4f, 0f);
                }
            }
        })

(() =>
        {
            var activeService = DaoAnProgressionService.Instance ?? service;
            if (activeService == null)
            {
                Debug.LogWarning("[DaoAn] Service is null!");
                return;
            }
            if (activeService.TryPurchase(node.id))
            {
                if (AudioManager.Instance != null) AudioManager.Instance.PlayClickSFX();
                GameLogger.Instance?.Log($"Khai mở Đạo Ấn: {node.displayName} Cấp {activeService.GetLevel(node.id)}!", Color.green);
                Refresh();
            }
        })

(() =>
        {
            if (activeDemonGoList.Contains(go))
            {
                SpawnFloatingText("-150.000 (Trảm!)", rt.anchoredPosition, new Color(1f, 0.4f, 0.2f), 1.2f);
                SpawnHitSpark(rt.anchoredPosition, Color.yellow, 64f);
                activeDemonGoList.Remove(go);
                Destroy(go);
                hordeKilled++;
                currentScore = hordeKilled;
                UpdateHordeScoreUI();
                ShakeArena(0.12f, 4f);
                if (hordeKilled >= HORDE_TARGET) EndMiniGame();
            }
        })

(() =>
        {
            if (activeThunderOrbs.Contains(go))
            {
                activeThunderOrbs.Remove(go);
                SpawnHitSpark(rt.anchoredPosition, Color.cyan, 60f);
                SpawnFloatingText("+1 LÔI TINH!", rt.anchoredPosition, Color.cyan, 1.2f);
                Destroy(go);
                orbsCollected++;
                currentScore = orbsCollected;
                UpdateLightningScoreUI();
                ShakeArena(0.08f, 3f);
                if (orbsCollected >= ORBS_TARGET) EndMiniGame();
            }
        })

(() =>
            {
                if (shopPanel != null)
                {
                    shopPanel.SetActive(!isCloseButton);
                }
                else
                {
                    GameObject p = GameObject.Find("Canvas")?.transform.Find("ShopPanel")?.gameObject;
                    if (p != null) p.SetActive(!isCloseButton);
                }
            })

(() =>
            {
                if (FeatureUnlockService.Instance != null && !FeatureUnlockService.Instance.IsDismantleUnlocked())
                {
                    if (GameLogger.Instance != null)
                    {
                        GameLogger.Instance.Log(FeatureUnlockService.Instance.GetFeatureUnlockRequirementText(FeatureId.Dismantle), Color.yellow);
                    }
                    return;
                }
                onClick.Invoke();
            })

animationAndStateEvidence.arguments:
("Xác nhận xóa", "Bạn có chắc muốn xóa nhân vật này? Dữ liệu không thể khôi phục.", 
        () => {
            dataManager.gameSaveData.slots[slotIndex] = new CharacterSaveData();
            dataManager.SaveData();
            UpdateMainMenuPlayButton();
            OpenCharacterSelection(); // Refresh UI
            confirmationPopup.SetActive(false);
        }, 
        () => {
            confirmationPopup.SetActive(false);
        })

("Vào game", $"Bắt đầu tu tiên với nhân vật {data.characterName}?", 
        () => {
            ConfirmEnterGame(slotIndex, data);
        }, 
        () => {
            confirmationPopup.SetActive(false);
        })

("Thoát game", "Bạn có muốn thoát game?", 
        () => {
            Application.Quit();
#if UNITY_EDITOR
            UnityEditor.EditorApplication.isPlaying = false;
#endif
        }, 
        () => {
            confirmationPopup.SetActive(false);
        })

(rewarded =>
            {
                if (!adInProgress) return; // SDK có thể gọi callback lặp.
                adInProgress = false;
                if (rewarded && OfflineEarningsManager.Instance != null && OfflineEarningsManager.Instance.HasPendingReward)
                {
                    OfflineEarningsManager.Instance.ClaimReward(2.0f);
                    CloseModal();
                }
                else
                {
                    if (claimNormalButton != null) claimNormalButton.interactable = true;
                    if (claimDoubleButton != null) claimDoubleButton.interactable = RewardedAdBridge.IsReady;
                }
                if (closeButton != null) closeButton.interactable = true;
            })

(
            "TRỞ VỀ MAIN MENU",
            "Đạo hữu có muốn <color=#FFE666>lưu lại toàn bộ tiến trình</color> và trở về Màn Hình Chính không?",
            () =>
            {
                // 1. Đồng bộ lưu dữ liệu triệt để
                SyncAndSaveGame();

                // 2. Mở khóa TimeScale trước khi chuyển Scene
                Time.timeScale = 1f;

                // 3. Nạp lại Scene để MainMenuManager tái khởi tạo giao diện chuẩn
                SceneManager.LoadScene(SceneManager.GetActiveScene().name);
            }
        )

(
            "THOÁT TRÒ CHƠI",
            "Đạo hữu có muốn <color=#FFE666>lưu lại tiến trình hiện tại</color> và thoát game không?",
            () =>
            {
                // 1. Đồng bộ lưu dữ liệu triệt để
                SyncAndSaveGame();

                // 2. Khôi phục thời gian
                Time.timeScale = 1f;

                // 3. Thoát Game
#if UNITY_EDITOR
                UnityEditor.EditorApplication.isPlaying = false;
#else
                Application.Quit();
#endif
            }
        )

(
                    $"{swordName} (Lv.{level})",
                    $"{detail} {(isEquipped ? "\nKiếm này đang xuất trận trên chiến trường!" : "")}",
