methods.body:
{
    RequireEditMode();
    foreach (Scene scene in Enumerable.Range(0, SceneManager.sceneCount).Select(SceneManager.GetSceneAt))
        if (scene.isDirty) throw new InvalidOperationException("Save open scenes before creating the PC workspace.");
    SceneSetup[] previous = EditorSceneManager.GetSceneManagerSetup();
    try
    {
        EnsureFolder(Root + "/Scenes");
        EnsureFolder(Root + "/Content/Opening/Prefabs");
        EnsureFolder(Root + "/Content/Opening/Materials");
        if (AssetDatabase.LoadAssetAtPath<GameObject>(ChunkPrefab) == null) CreateChunkPrefab();
        if (AssetDatabase.LoadAssetAtPath<SceneAsset>(PCScene) == null)
        {
            if (!AssetDatabase.CopyAsset(AndroidScene, PCScene))
                throw new InvalidOperationException("Could not copy the saved Android source scene.");
            Scene pc = EditorSceneManager.OpenScene(PCScene, OpenSceneMode.Additive);
            var marker = new GameObject("__PCWorkspace_SaveIsolation");
            SceneManager.MoveGameObjectToScene(marker, pc);
            marker.AddComponent<WorkspaceSaveProfile>().profileId = ProfileId;
            var contentRoot = new GameObject("PCContent_IntegrationRoot");
            SceneManager.MoveGameObjectToScene(contentRoot, pc);
            // The source can be saved in direct-gameplay debug mode. Restore its
            // existing menu only in the new PC copy so sessions load/save normally.
            foreach (GameObject root in pc.GetRootGameObjects())
                foreach (MonoBehaviour component in root.GetComponentsInChildren<MonoBehaviour>(true))
                    if (component != null && component.GetType().Name == "MainMenuManager")
                        for (Transform item = component.transform; item != null; item = item.parent)
                            item.gameObject.SetActive(true);
            EditorSceneManager.SaveScene(pc);
            EditorSceneManager.CloseScene(pc, true);
        }
        if (AssetDatabase.LoadAssetAtPath<SceneAsset>(SandboxScene) == null) CreateSandbox();
        AssetDatabase.SaveAssets();
    }
    finally { EditorSceneManager.RestoreSceneManagerSetup(previous); }
    ValidateWorkspace();
}

{
    RequireEditMode();
    if (EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())
        EditorSceneManager.OpenScene(PCScene, OpenSceneMode.Single);
}

{
    RequireEditMode();
    if (EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())
        EditorSceneManager.OpenScene(SandboxScene, OpenSceneMode.Single);
}

{
    RequireEditMode();
    foreach (Scene scene in Enumerable.Range(0, SceneManager.sceneCount).Select(SceneManager.GetSceneAt))
        if (scene.isDirty) throw new InvalidOperationException("Save open scenes before validating the PC workspace.");
    if (AssetDatabase.AssetPathToGUID(AndroidScene) == AssetDatabase.AssetPathToGUID(PCScene))
        throw new InvalidOperationException("PC and Android scene GUIDs must differ.");
    if (EditorBuildSettings.scenes.Any(s => s.path == PCScene || s.path == SandboxScene))
        throw new InvalidOperationException("Workspace scenes must not be in the Android global build list.");
    SceneSetup[] previous = EditorSceneManager.GetSceneManagerSetup();
    try
    {
        Scene pc = OpenForValidation(PCScene);
        CheckMissingScripts(pc);
        if (WorkspaceSaveProfile.Resolve(pc) != ProfileId)
            throw new InvalidOperationException("PC scene save isolation is missing or has been changed.");
        Scene sandbox = OpenForValidation(SandboxScene);
        CheckMissingScripts(sandbox);
        foreach (GameObject root in sandbox.GetRootGameObjects())
            foreach (MonoBehaviour component in root.GetComponentsInChildren<MonoBehaviour>(true))
                if (component != null && component.GetType().Assembly.GetName().Name == "Assembly-CSharp")
                    throw new InvalidOperationException("Sandbox contains a shared gameplay component: " + component.GetType().Name);
        GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(ChunkPrefab);
        if (prefab == null || prefab.GetComponent<ContentChunk>() == null)
            throw new InvalidOperationException("Content chunk template is missing.");
        foreach (MonoBehaviour component in prefab.GetComponentsInChildren<MonoBehaviour>(true))
            if (component == null || !(component is ContentChunk))
                throw new InvalidOperationException("Content prefab may only contain the ContentChunk authoring behaviour.");
    }
    finally { EditorSceneManager.RestoreSceneManagerSetup(previous); }
    Debug.Log("[PCWorkspace] PASS: independent scene GUIDs, isolated save, no missing scripts, clean sandbox, Android build list preserved.");
}

{
    BuildWindowsAtPath(Path.GetFullPath("Builds/PCContent/KhiVanChiTu_PC.exe"));
}

{
    RequireEditMode();
    ValidateWorkspace();
    if (EditorUserBuildSettings.activeBuildTarget != BuildTarget.StandaloneWindows64)
        throw new InvalidOperationException("Use the collaborator's checkout with Windows active. This tool does not switch the Android checkout's build target.");
    if (!BuildPipeline.IsBuildTargetSupported(BuildTargetGroup.Standalone, BuildTarget.StandaloneWindows64))
        throw new InvalidOperationException("Install Windows build support for Unity 6000.6.4f1.");
    if (File.Exists(outputPath)) throw new IOException("Output already exists. Choose a new build directory: " + outputPath);
    Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(outputPath)));
    BuildReport report = BuildPipeline.BuildPlayer(new BuildPlayerOptions
    {
        scenes = new[] { PCScene },
        locationPathName = outputPath,
        target = BuildTarget.StandaloneWindows64,
        options = BuildOptions.Development
    });
    if (report.summary.result != BuildResult.Succeeded)
        throw new InvalidOperationException("Windows build failed: " + report.summary.result);
    Debug.Log("[PCWorkspace] Windows development build: " + outputPath);
}

{
    string materialPath = Root + "/Content/Opening/Materials/OpeningGround.mat";
    Material material = AssetDatabase.LoadAssetAtPath<Material>(materialPath);
    if (material == null)
    {
        Shader shader = Shader.Find("Universal Render Pipeline/Lit");
        if (shader == null) throw new InvalidOperationException("URP Lit shader is unavailable.");
        material = new Material(shader) { color = new Color(0.18f, 0.28f, 0.23f) };
        AssetDatabase.CreateAsset(material, materialPath);
    }
    var root = new GameObject("OpeningChunkTemplate");
    try
    {
        root.AddComponent<ContentChunk>();
        CreateBlock(root.transform, "Ground_24x80", new Vector3(0, -0.25f, 40), new Vector3(24, 0.5f, 80), material);
        for (int i = 0; i < 4; i++)
        {
            CreateBlock(root.transform, "LeftMarker_" + i, new Vector3(-10, 1, 10 + i * 20), new Vector3(1, 2, 1), material);
            CreateBlock(root.transform, "RightMarker_" + i, new Vector3(10, 1, 10 + i * 20), new Vector3(1, 2, 1), material);
        }
        PrefabUtility.SaveAsPrefabAsset(root, ChunkPrefab);
    }
    finally { Object.DestroyImmediate(root); }
}

{
    GameObject block = GameObject.CreatePrimitive(PrimitiveType.Cube);
    block.name = name;
    block.transform.SetParent(parent, false);
    block.transform.localPosition = position;
    block.transform.localScale = scale;
    block.GetComponent<Renderer>().sharedMaterial = material;
}

{
    Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Additive);
    SceneManager.SetActiveScene(scene);
    var environment = new GameObject("EnvironmentPreview");
    var loop = environment.AddComponent<ContentPreviewLoop>();
    loop.chunks = new ContentChunk[2];
    GameObject prefab = AssetDatabase.LoadAssetAtPath<GameObject>(ChunkPrefab);
    for (int i = 0; i < 2; i++)
    {
        var chunk = (GameObject)PrefabUtility.InstantiatePrefab(prefab, scene);
        chunk.name = "OpeningChunk_" + (i + 1);
        chunk.transform.SetParent(environment.transform, false);
        chunk.transform.localPosition = new Vector3(0, 0, i * 80f);
        loop.chunks[i] = chunk.GetComponent<ContentChunk>();
    }
    var cameraObject = new GameObject("Sandbox Camera", typeof(Camera), typeof(AudioListener));
    cameraObject.tag = "MainCamera";
    cameraObject.transform.position = new Vector3(24, 32, -18);
    cameraObject.transform.LookAt(new Vector3(0, 0, 45));
    Camera camera = cameraObject.GetComponent<Camera>();
    camera.clearFlags = CameraClearFlags.SolidColor;
    camera.backgroundColor = new Color(0.06f, 0.09f, 0.14f);
    camera.farClipPlane = 400;
    var light = new GameObject("Sandbox Key Light", typeof(Light));
    light.GetComponent<Light>().type = LightType.Directional;
    light.transform.rotation = Quaternion.Euler(50, -30, 0);
    RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
    RenderSettings.ambientLight = new Color(0.5f, 0.5f, 0.5f);
    EditorSceneManager.SaveScene(scene, SandboxScene);
    EditorSceneManager.CloseScene(scene, true);
}

{
    Scene scene = SceneManager.GetSceneByPath(path);
    if (scene.IsValid() && scene.isLoaded) return scene;
    return EditorSceneManager.OpenScene(path, OpenSceneMode.Additive);
}

{
    foreach (GameObject root in scene.GetRootGameObjects())
        foreach (Transform item in root.GetComponentsInChildren<Transform>(true))
            if (GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(item.gameObject) != 0)
                throw new InvalidOperationException("Missing script in " + scene.path + ": " + item.name);
}

{
    if (AssetDatabase.IsValidFolder(path)) return;
    string parent = path.Substring(0, path.LastIndexOf('/'));
    EnsureFolder(parent);
    AssetDatabase.CreateFolder(parent, Path.GetFileName(path));
}

{
    if (EditorApplication.isPlayingOrWillChangePlaymode)
        throw new InvalidOperationException("Stop Play Mode before workspace authoring or building.");
}

{
    Gizmos.color = Color.cyan;
    Matrix4x4 previous = Gizmos.matrix;
    Gizmos.matrix = transform.localToWorldMatrix;
    Gizmos.DrawWireCube(new Vector3(0f, 0.5f, length * 0.5f), new Vector3(width, 1f, length));
    Gizmos.matrix = previous;
}

{
    if (chunks == null || chunks.Length < 2) return;
    foreach (ContentChunk chunk in chunks)
    {
        if (chunk == null) continue;
        chunk.transform.Translate(Vector3.back * (speed * Time.deltaTime), Space.World);
        if (chunk.transform.position.z + chunk.length >= originZ) continue;
        float front = float.NegativeInfinity;
        foreach (ContentChunk other in chunks)
            if (other != null && other != chunk)
                front = Mathf.Max(front, other.transform.position.z + other.length);
        if (float.IsNegativeInfinity(front)) continue;
        Vector3 position = chunk.transform.position;
        position.z = front;
        chunk.transform.position = position;
    }
}

{
    WorkspaceSaveProfile found = null;
    foreach (GameObject root in scene.GetRootGameObjects())
    {
        foreach (WorkspaceSaveProfile candidate in root.GetComponentsInChildren<WorkspaceSaveProfile>(true))
        {
            if (found != null)
                throw new InvalidOperationException("A gameplay scene must have at most one workspace save profile.");
            found = candidate;
        }
    }
    if (found == null) return string.Empty;
    ValidateId(found.profileId);
    if (string.IsNullOrEmpty(found.profileId))
        throw new ArgumentException("A workspace marker must have a non-empty profile ID.");
    return found.profileId;
}

{
    ValidateId(profile);
    return string.IsNullOrEmpty(profile) ? original : profile + "::" + original;
}

{
    ValidateId(profile);
    return string.IsNullOrEmpty(profile) ? original : profile + "_" + original;
}

{
    if (string.IsNullOrEmpty(profile)) return;
    if (profile.Length > 40) throw new ArgumentException("Workspace profile ID is too long.");
    foreach (char c in profile)
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '-' || c == '_'))
            throw new ArgumentException("Workspace profile ID may only contain ASCII letters, digits, '-' and '_'.");
}

{
    string profile = WorkspaceSaveProfile.Resolve(scene);
    Assert.That(WorkspaceSaveProfile.Key("KhiVanChiTu_SaveData", profile), Is.EqualTo("KhiVanChiTu_SaveData"));
    Assert.That(WorkspaceSaveProfile.FileName("KhiVanChiTu_SaveData.json", profile), Is.EqualTo("KhiVanChiTu_SaveData.json"));
}

{
    AddMarker("pc-workspace");
    string profile = WorkspaceSaveProfile.Resolve(scene);
    Assert.That(WorkspaceSaveProfile.Key("KhiVanChiTu_SaveData", profile), Is.EqualTo("pc-workspace::KhiVanChiTu_SaveData"));
    Assert.That(WorkspaceSaveProfile.FileName("KhiVanChiTu_SaveData.json", profile), Is.EqualTo("pc-workspace_KhiVanChiTu_SaveData.json"));
}

{
    AddMarker("pc-workspace").gameObject.SetActive(false);
    Assert.That(WorkspaceSaveProfile.Resolve(scene), Is.EqualTo("pc-workspace"));
}

{
    AddMarker("pc-one");
    AddMarker("pc-two");
    Assert.Throws<InvalidOperationException>(() => WorkspaceSaveProfile.Resolve(scene));
}

{
    AddMarker("");
    Assert.Throws<ArgumentException>(() => WorkspaceSaveProfile.Resolve(scene));
}

{
    Assert.Throws<ArgumentException>(() => WorkspaceSaveProfile.FileName("save.json", profile));
}

{
    var markerObject = new GameObject("TestSaveProfile");
    SceneManager.MoveGameObjectToScene(markerObject, scene);
    WorkspaceSaveProfile marker = markerObject.AddComponent<WorkspaceSaveProfile>();
    marker.profileId = id;
    return marker;
}

    {
        // Xóa child cũ nếu có
        for (int i = transform.childCount - 1; i >= 0; i--)
        {
            Destroy(transform.GetChild(i).gameObject);
        }

        // 1. Load Materials chuẩn URP
        Material taijiMat = null;
        Material whiteGlowMat = null;
        Material blackYinMat = null;
#if UNITY_EDITOR
        taijiMat = UnityEditor.AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/VFX/Mat_YinYangTaiji_URP.mat");
        whiteGlowMat = UnityEditor.AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/VFX/Mat_LightningGlow_URP.mat");
        blackYinMat = UnityEditor.AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/VFX/Mat_YinBlack_URP.mat");
#endif
        Shader urpParticles = Shader.Find("Universal Render Pipeline/Particles/Unlit") ?? Shader.Find("Sprites/Default");
        if (taijiMat == null) taijiMat = new Material(urpParticles);
        if (whiteGlowMat == null) whiteGlowMat = new Material(urpParticles);
        if (blackYinMat == null)
        {
            blackYinMat = new Material(urpParticles);
            blackYinMat.color = new Color(0.04f, 0.04f, 0.06f, 0.95f);
        }

        // 2. Ground Taiji Disc (Vòng Thái Cực Đen - Trắng chuẩn Đạo Gia)
        groundDiscObj = GameObject.CreatePrimitive(PrimitiveType.Quad);
        groundDiscObj.name = "TaijiGroundDisc";
        groundDiscObj.transform.SetParent(transform, false);
        groundDiscObj.transform.localPosition = new Vector3(0f, 0.04f, 0f);
        groundDiscObj.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
        groundDiscObj.transform.localScale = new Vector3(DISC_SIZE, DISC_SIZE, 1f);
        Destroy(groundDiscObj.GetComponent<Collider>());
        var rDisc = groundDiscObj.GetComponent<MeshRenderer>();
        if (rDisc != null) rDisc.sharedMaterial = taijiMat;

        // 3. Luồng Dương (Bạch Quang - Pure Radiant White)
        yangOrb = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        yangOrb.name = "Yang_WhiteRadiance";
        yangOrb.transform.SetParent(transform, false);
        yangOrb.transform.localScale = Vector3.one * 0.24f;
        Destroy(yangOrb.GetComponent<Collider>());
        var rYang = yangOrb.GetComponent<MeshRenderer>();
        if (rYang != null) rYang.sharedMaterial = whiteGlowMat;

        TrailRenderer trYang = yangOrb.AddComponent<TrailRenderer>();
        trYang.time = 0.42f;
        trYang.startWidth = 0.28f;
        trYang.endWidth = 0.02f;
        trYang.material = whiteGlowMat;
        trYang.startColor = new Color(1f, 1f, 1f, 0.95f);
        trYang.endColor = new Color(1f, 1f, 1f, 0f);

        // 4. Luồng Âm (Hắc Diệu Thạch - Deep Obsidian Black)
        yinOrb = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        yinOrb.name = "Yin_BlackObsidian";
        yinOrb.transform.SetParent(transform, false);
        yinOrb.transform.localScale = Vector3.one * 0.24f;
        Destroy(yinOrb.GetComponent<Collider>());
        var rYin = yinOrb.GetComponent<MeshRenderer>();
        if (rYin != null) rYin.sharedMaterial = blackYinMat;

        TrailRenderer trYin = yinOrb.AddComponent<TrailRenderer>();
        trYin.time = 0.42f;
        trYin.startWidth = 0.28f;
        trYin.endWidth = 0.02f;
        trYin.material = blackYinMat;
        trYin.startColor = new Color(0.04f, 0.04f, 0.06f, 0.92f);
        trYin.endColor = new Color(0.04f, 0.04f, 0.06f, 0f);

        UpdatePositions();
    }

{
    currentAngle += orbRotateSpeed * Time.deltaTime;
    if (currentAngle >= 360f) currentAngle -= 360f;

    currentDiscAngle += discRotateSpeed * Time.deltaTime;
