public static BossDamageVignette Instance
{
    get
    {
        if (_instance == null)
        {
            CreateAutoInstance();
        }
        return _instance;
    }
}

methods.body:
    {
        if (_instance == null)
        {
            _instance = this;
        }
        else if (_instance != this)
        {
            Destroy(gameObject);
            return;
        }

        SetupUI();
    }

    {
        // Tự động tìm Canvas trong Scene
        Canvas targetCanvas = FindObjectOfType<Canvas>();
        if (targetCanvas == null)
        {
            Debug.LogWarning("[BossDamageVignette] Không tìm thấy Canvas trong Scene!");
            return;
        }

        // Tạo GameObject độc lập con của Canvas
        GameObject vignetteObj = new GameObject("BossDamageVignetteOverlay", typeof(RectTransform));
        vignetteObj.transform.SetParent(targetCanvas.transform, false);
        _instance = vignetteObj.AddComponent<BossDamageVignette>();
    }

    {
        RectTransform rt = GetComponent<RectTransform>();
        if (rt == null) rt = gameObject.AddComponent<RectTransform>();

        // Mobile portrait: phủ trọn màn hình, không giữ giới hạn nửa trái của UI desktop.
        rt.anchorMin = new Vector2(0f, 0f);
        rt.anchorMax = Vector2.one;
        rt.pivot = new Vector2(0.5f, 0.5f);
        rt.offsetMin = Vector2.zero;
        rt.offsetMax = Vector2.zero;

        // Cho overlay xuống dưới các popup text nhưng trên nền combat
        transform.SetAsLastSibling();

        canvasGroup = GetComponent<CanvasGroup>();
        if (canvasGroup == null) canvasGroup = gameObject.AddComponent<CanvasGroup>();
        canvasGroup.alpha = 0f;
        canvasGroup.blocksRaycasts = false;
        canvasGroup.interactable = false;

        // 1. Tạo hình nền Vignette viền đỏ mềm (Gradient viền tỏa vào tâm)
        GameObject vignetteImgObj = new GameObject("VignetteGlow", typeof(RectTransform), typeof(Image));
        vignetteImgObj.transform.SetParent(transform, false);
        RectTransform vRt = vignetteImgObj.GetComponent<RectTransform>();
        vRt.anchorMin = Vector2.zero;
        vRt.anchorMax = Vector2.one;
        vRt.sizeDelta = Vector2.zero;

        Image vignetteImg = vignetteImgObj.GetComponent<Image>();
        vignetteImg.raycastTarget = false;
        vignetteImg.color = new Color(1f, 0.05f, 0.05f, 0.75f); // Đỏ rực
        vignetteImg.sprite = GetOrCreateVignetteSprite();

        // 2. Tạo thêm 4 dải viền ngoài cùng đậm nét (Edge borders)
        CreateEdgeBorder("TopBorder", new Vector2(0, 1), new Vector2(1, 1), new Vector2(0.5f, 1), new Vector2(0, 20), new Color(1f, 0f, 0f, 0.9f));
        CreateEdgeBorder("BottomBorder", new Vector2(0, 0), new Vector2(1, 0), new Vector2(0.5f, 0), new Vector2(0, 20), new Color(1f, 0f, 0f, 0.9f));
        CreateEdgeBorder("LeftBorder", new Vector2(0, 0), new Vector2(0, 1), new Vector2(0, 0.5f), new Vector2(20, 0), new Color(1f, 0f, 0f, 0.9f));
        CreateEdgeBorder("RightBorder", new Vector2(1, 0), new Vector2(1, 1), new Vector2(1, 0.5f), new Vector2(20, 0), new Color(1f, 0f, 0f, 0.9f));
    }

{
    GameObject edgeObj = new GameObject(name, typeof(RectTransform), typeof(Image));
    edgeObj.transform.SetParent(transform, false);
    RectTransform edgeRt = edgeObj.GetComponent<RectTransform>();
    edgeRt.anchorMin = anchorMin;
    edgeRt.anchorMax = anchorMax;
    edgeRt.pivot = pivot;
    edgeRt.sizeDelta = sizeDelta;
    
    Image img = edgeObj.GetComponent<Image>();
    img.color = color;
    img.raycastTarget = false;
}

    {
        if (vignetteTexture == null)
        {
            int size = 64;
            vignetteTexture = new Texture2D(size, size, TextureFormat.RGBA32, false);
            vignetteTexture.wrapMode = TextureWrapMode.Clamp;
            
            Color[] pixels = new Color[size * size];
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float u = (float)x / (size - 1);
                    float v = (float)y / (size - 1);
                    
                    // Khoảng cách tới mép gần nhất (0 ở viền, 0.5 ở tâm)
                    float edgeDist = Mathf.Min(u, 1f - u, v, 1f - v);
                    // Biên đỏ tỏa sâu vào trong 40%
                    float alpha = Mathf.Clamp01(1f - (edgeDist / 0.35f));
                    alpha = Mathf.Pow(alpha, 1.8f); // Cong mượt
                    
                    pixels[y * size + x] = new Color(1f, 1f, 1f, alpha);
                }
            }
            vignetteTexture.SetPixels(pixels);
            vignetteTexture.Apply();
        }

        return Sprite.Create(vignetteTexture, new Rect(0, 0, vignetteTexture.width, vignetteTexture.height), new Vector2(0.5f, 0.5f));
    }

{
    if (Instance != null)
    {
        Instance.DoFlash();
    }
}

{
    if (canvasGroup == null) return;
    
    if (flashCoroutine != null)
    {
        StopCoroutine(flashCoroutine);
    }
    flashCoroutine = StartCoroutine(FlashRoutine());
}

    {
        // 1. Chớp đỏ mạnh tức thì
        canvasGroup.alpha = 0.95f;
        yield return new WaitForSecondsRealtime(0.04f);

        // 2. Mờ dần mượt mà trong 0.4 giây
        float duration = 0.4f;
        float elapsed = 0f;

        while (elapsed < duration)
        {
            elapsed += Time.unscaledDeltaTime;
            float t = elapsed / duration;
            canvasGroup.alpha = Mathf.Lerp(0.95f, 0f, Mathf.SmoothStep(0f, 1f, t));
            yield return null;
        }

        canvasGroup.alpha = 0f;
        flashCoroutine = null;
    }

{
    if (flashCoroutine != null)
    {
        StopCoroutine(flashCoroutine);
        flashCoroutine = null;
    }
    if (canvasGroup != null) canvasGroup.alpha = 0f;
}

{
    base.Awake();
    CacheAnimatorParameters();
}

{
    CancelInvoke();
    if (attackRoutine != null)
    {
        StopCoroutine(attackRoutine);
        attackRoutine = null;
    }
    isAttackingAnimation = false;
    isMovingState = false;
    isDead = false;
}

    {
        float baseHp;
        if (stage <= 1) baseHp = 350f;
        else if (stage == 2) baseHp = 750f;
        else if (stage == 3) baseHp = 1400f;
        else if (stage == 4) baseHp = 2500f;
        else
        {
            float stageScale = (stage - 5) / 5f;
            baseHp = 4000f * Mathf.Pow(2.2f, stageScale);
        }

        if (isTribulation) baseHp *= 1.35f;
        return baseHp;
    }

    {
        float finalDamage;
        if (stage <= 1) finalDamage = 8f;
        else if (stage == 2) finalDamage = 14f;
        else if (stage == 3) finalDamage = 22f;
        else if (stage == 4) finalDamage = 32f;
        else finalDamage = 45f + ((stage - 5) / 5f) * 25f;

        if (isTribulation) finalDamage *= 1.25f;
        return finalDamage;
    }

    {
        float finalHealth = CalculateBossHealth(stage, isTribulation);

        if (this.hpBarHeight < 3.2f) this.hpBarHeight = 3.5f;
        this.attackRange = 2.4f;
        this.moveSpeed = 1.8f;
        this.isTribulationBoss = false;
        this.currentPhase = 1;
        this.damageReductionPercent = 0f;
        this.attackInterval = 1.5f;

        base.Init(finalHealth, target, true);
        var guard = GetComponent<OpeningBossGuard>();
        if (stage == 10)
        {
            if (guard == null) guard = gameObject.AddComponent<OpeningBossGuard>();
            guard.ResetGuard(finalHealth * 0.3f);
        }
        else if (guard != null) guard.ResetGuard(0);

        Transform hpCanvas = transform.Find("HPCanvas");
        if (hpCanvas != null)
        {
            hpCanvas.localPosition = new Vector3(0, hpBarHeight, 0);
            Transform pTxt = hpCanvas.Find("PhaseText");
            if (pTxt != null) pTxt.gameObject.SetActive(false);
        }

        float finalDamage = CalculateBossDamage(stage, isTribulation);
        this.damage = finalDamage;
        this.baseScale = Vector3.one * 1.5f;
        transform.localScale = this.baseScale;

        isMovingState = false;
        isAttackingAnimation = false;
        attackTimer = 0.5f;

        CacheAnimatorParameters();
        SetMoving(false);
        if (animator != null)
        {
            animator.applyRootMotion = false;
            animator.ResetTrigger("Die");
            animator.ResetTrigger("Attack");
            animator.SetBool(HashIsMoving, false);
            animator.Play("idle", 0, 0f);
        }
    }

{
    int stageIdx = CultivationManager.Instance != null ? CultivationManager.Instance.currentStageIndex : 0;
    InitTribulationBoss(realmTier, stageIdx, targetRealmName, target);
}

    {
        var openingGuard = GetComponent<OpeningBossGuard>();
        if (openingGuard != null) openingGuard.ResetGuard(0);
        this.isBoss = true;
        this.isTribulationBoss = true;
        this.playerTarget = target;
        this.attackRange = 2.4f;
        this.hpBarHeight = 3.6f;

        this.currentPhase = 1;

        // Tốc độ di chuyển nhanh mạnh mẽ (3.2m/s) để áp sát player chỉ trong ~2.5 - 3 giây
        this.moveSpeed = 3.2f;
        // Đợt tấn công hoạt động chuẩn theo Animation và lặp lại sau mỗi 1.5s
        this.attackInterval = 1.5f;

        // --- PHÂN CHIA CHỈ SỐ MÁU VÀ KHÁNG SÁT THƯƠNG THEO TỪNG CẢNH GIỚI TU VI ---
        float hp;
        float dmgReduction;

        switch (realmTier)
        {
            case 1: // Luyện Khí Tầng 15 -> Trúc Cơ Sơ Kỳ
                // Người chơi ở giai đoạn đầu (kiếm lv 2-3, dame ~80-150): Máu vừa tầm 1,800 HP để đánh 15-20 hit
                hp = 1800f;
                dmgReduction = 0.15f; // Kháng 15%
                break;

            case 2: // Trúc Cơ Hậu Kỳ -> Kết Đan Sơ Kỳ
                // Người chơi đã mở Vạn Kiếm Quy Tông (20 kiếm chém dồn), kiếm lv 4-6
                hp = 25000f;
                dmgReduction = 0.25f; // Kháng 25%
                break;

            case 3: // Kết Đan Hậu Kỳ -> Nguyên Anh Sơ Kỳ
                // Kiếm lv 7-10, buff Tu Lực nhân nhiều lần
                hp = 350000f;
                dmgReduction = 0.35f;
                break;

            case 4: // Nguyên Anh Hậu Kỳ -> Hóa Thần Sơ Kỳ
                hp = 4500000f;
                dmgReduction = 0.45f;
                break;

            case 5: // Hóa Thần Hậu Kỳ -> Đỉnh Phong
                hp = 50000000f;
                dmgReduction = 0.50f;
                break;

            default:
                // Tự động nội suy theo tầng tu vi cụ thể nếu dùng cheat test
                hp = 1800f * Mathf.Pow(2.2f, Mathf.Max(0, (stageIndex - 14) / 3f));
                dmgReduction = Mathf.Clamp(0.15f + (realmTier * 0.08f), 0.15f, 0.55f);
                break;
        }

        this.damageReductionPercent = dmgReduction;

        // Giữ nguyên kích thước cơ bản hài hòa, KHÔNG phóng to quá đà
        this.baseScale = Vector3.one * 1.5f;
        transform.localScale = this.baseScale;

        // Gọi Init lớp cha
        base.Init(hp, target, true);

        // Khởi tạo UI hiển thị Phase trên thanh máu
        SetupTribulationHPBar();

        isMovingState = false;
        isAttackingAnimation = false;
        if (attackRoutine != null)
        {
            StopCoroutine(attackRoutine);
            attackRoutine = null;
        }

        // Khi vừa tiếp cận, chờ 0.2s để chuyển từ thế chạy sang thế đánh
        attackTimer = 0.2f;

        CacheAnimatorParameters();
        SetMoving(false);
        if (animator != null)
        {
            animator.applyRootMotion = false;
            animator.ResetTrigger("Die");
            animator.ResetTrigger("Attack");
            animator.SetBool(HashIsMoving, false);
            animator.Play("idle", 0, 0f);
        }

        Debug.Log($"⚡ [BossEnemy] Sinh Boss Thiên Kiếp (3 Phase)! Đột phá: {targetRealmName} (Tier {realmTier}), Tổng Máu: {hp:N0}, Kháng ST Phase 1: {dmgReduction * 100:F0}%");
    }

    {
        Transform hpCanvas = transform.Find("HPCanvas");
        if (hpCanvas != null)
        {
            hpCanvas.localPosition = new Vector3(0, hpBarHeight, 0);

            Transform phaseTr = hpCanvas.Find("PhaseText");
            if (phaseTr == null)
            {
                GameObject phaseObj = new GameObject("PhaseText", typeof(RectTransform), typeof(Text), typeof(Outline));
                phaseObj.transform.SetParent(hpCanvas, false);
                phaseTextUI = phaseObj.GetComponent<Text>();
                phaseTextUI.alignment = TextAnchor.MiddleCenter;
                phaseTextUI.fontSize = 14;
                phaseTextUI.fontStyle = FontStyle.Bold;
                phaseObj.GetComponent<Outline>().effectColor = Color.black;
                RectTransform pRt = phaseObj.GetComponent<RectTransform>();
                pRt.anchoredPosition = new Vector2(0, 0.28f);
                pRt.sizeDelta = new Vector2(3.5f, 0.4f);
            }
            else
            {
                phaseTextUI = phaseTr.GetComponent<Text>();
                phaseTextUI.gameObject.SetActive(true);
            }

            Font f = UiTextStyle.BodyFont;
            if (phaseTextUI != null && f != null) phaseTextUI.font = f;
        }

        UpdatePhaseVisuals(1);
    }

    {
        if (phaseTextUI != null)
        {
            switch (phase)
            {
                case 1:
                    phaseTextUI.text = "[PHASE 1/3] Kim Cương Thể";
                    phaseTextUI.color = new Color(1f, 0.85f, 0.2f); // Cam vàng
                    break;
                case 2:
                    phaseTextUI.text = "[PHASE 2/3] Lôi Giáp Bạo Phát";
                    phaseTextUI.color = new Color(0.9f, 0.45f, 1f); // Tím lôi điện
                    break;
                case 3:
                    phaseTextUI.text = "[PHASE 3/3] Cuồng Nộ Diệt Thế";
                    phaseTextUI.color = new Color(1f, 0.25f, 0.25f); // Đỏ rực ma lôi
                    break;
            }
        }

        if (hpFill != null)
        {
            switch (phase)
            {
                case 1:
                    hpFill.color = new Color(1f, 0.75f, 0.1f); // Cam vàng
                    break;
                case 2:
                    hpFill.color = new Color(0.85f, 0.3f, 1f); // Tím lôi điện
                    break;
                case 3:
                    hpFill.color = new Color(1f, 0.15f, 0.15f); // Đỏ rực
                    break;
            }
        }
    }

    {
        if (animator == null)
        {
            animator = GetComponentInChildren<Animator>();
            if (animator == null) animator = GetComponentInParent<Animator>();
        }

        hasHashIsMoving = false;
        hasHashAttack = false;
        hasHashDie = false;

        if (animator != null)
        {
            foreach (var p in animator.parameters)
            {
                if (p.name == "IsMoving" && p.type == AnimatorControllerParameterType.Bool) hasHashIsMoving = true;
                if (p.name == "Attack" && p.type == AnimatorControllerParameterType.Trigger) hasHashAttack = true;
                if (p.name == "Die" && p.type == AnimatorControllerParameterType.Trigger) hasHashDie = true;
            }
        }
    }

    {
        if (playerTarget == null || isDead) return;

        Vector3 currentPos = transform.position;
        Vector3 targetPos = new Vector3(playerTarget.position.x, currentPos.y, playerTarget.position.z);

        // 1. Luôn xoay mượt mặt nhìn thẳng về phía Player
        Vector3 lookDir = (targetPos - currentPos).normalized;
        if (lookDir.sqrMagnitude > 0.001f)
        {
            Quaternion targetRot = Quaternion.LookRotation(lookDir);
            float currentTurnSpeed = isAttackingAnimation ? (turnSpeed * 0.4f) : turnSpeed;
            transform.rotation = Quaternion.RotateTowards(transform.rotation, targetRot, currentTurnSpeed * Time.deltaTime);
        }

        // 2. Nếu đang trong tiến trình hoạt ảnh tấn công: Đứng yên hoàn tất động tác chém
        if (isAttackingAnimation)
        {
            SetMoving(false);
            return;
        }

        // 3. Tính khoảng cách 2D mặt phẳng X-Z (bỏ qua trục Y độ cao)
        float dist = Vector2.Distance(new Vector2(currentPos.x, currentPos.z), new Vector2(targetPos.x, targetPos.z));

        // 4. Phân nhánh hành vi:
        if (dist > attackRange)
        {
            // Ở ngoài tầm đánh: Di chuyển tiến sát Player
            float formationSlow = FormationService.Instance != null ? FormationService.Instance.BossSpeedMultiplier : 1f;
            transform.position = Vector3.MoveTowards(transform.position, targetPos, moveSpeed * formationSlow * Time.deltaTime);
            SetMoving(true);
        }
        else
        {
            // Đã vào tầm đánh cận chiến: Dừng chân
            SetMoving(false);

            if (attackTimer > 0f)
            {
                attackTimer -= Time.deltaTime;
            }
            else
            {
                // BẮT ĐẦU ĐỢT TẤN CÔNG THEO ANIMATION VÀ SAU MỖI 1.5S
                attackTimer = attackInterval;
                if (attackRoutine != null) StopCoroutine(attackRoutine);
                attackRoutine = StartCoroutine(PerformAttackCycleRoutine());
            }
        }
    }

    {
        isAttackingAnimation = true;
        SetMoving(false);

        // 1. Bắt đầu hoạt cảnh tấn công
        if (animator != null && hasHashAttack)
        {
            animator.ResetTrigger(HashAttack);
            animator.SetTrigger(HashAttack);
        }

        // Bổ sung: Wind-up Visual tại giây 0.00!
        if (HitVFXManager.Instance != null)
        {
            Vector3 handPos = transform.position + transform.forward * 1.2f + Vector3.up * 2f;
            HitVFXManager.Instance.SpawnBossWindUp(handPos);
        }

        // 2. Chờ đúng thời điểm tay Boss chém chạm vào mục tiêu theo Animation (Wind-up Delay)
        yield return new WaitForSeconds(0.48f);

        // 3. GÂY SÁT THƯƠNG ĐÚNG THỜI ĐIỂM CHẠM ĐÍCH
        if (!isDead && playerTarget != null)
        {
            Vector3 impactPos = (playerTarget.position + transform.position) * 0.5f + Vector3.up * 0.1f;
            if (HitVFXManager.Instance != null)
            {
                HitVFXManager.Instance.SpawnBossGroundImpact(impactPos);
            }

            float finalDmg = damage;

            // QUY TẮC CỐT LÕI: Boss Thiên Kiếp gây đúng 15% Max HP của Player mỗi đòn đánh!
            // 7 nhát trúng đích = 105% HP -> Player CHẮC CHẮN TỬ TRẬN!
            if (isTribulationBoss && CombatManager.Instance != null)
            {
                finalDmg = CombatManager.Instance.playerMaxHp * 0.15f;
            }

            if (CombatManager.Instance != null)
            {
                CombatManager.Instance.DamagePlayer(finalDmg, true);
            }

            // Rung chấn màn hình tạo lực chém chân thực
            if (CameraShake.Instance != null)
            {
                CameraShake.Instance.TriggerShake(0.35f, 0.25f);
            }
        }

        // 4. Chờ hoàn tất phần còn lại của Animation và chu kỳ 1.5s (Recovery Cooldown)
        float remainingDuration = Mathf.Max(0.1f, 1.5f - 0.48f);
        yield return new WaitForSeconds(remainingDuration);

        isAttackingAnimation = false;
        attackRoutine = null;
    }

    {
        if (isMovingState == moving) return;
        isMovingState = moving;

        if (animator != null && hasHashIsMoving)
        {
            animator.SetBool(HashIsMoving, moving);
        }
    }

    {
        var guard = GetComponent<OpeningBossGuard>();
        if (!isTribulationBoss && guard != null) amount = guard.Absorb(amount);
        if (isTribulationBoss)
        {
            // 1. Damage Cap: Mỗi đòn đánh của phi kiếm/kỹ năng chỉ được gây tối đa 4% Max HP của Boss
            // (Đảm bảo người chơi phải tấn công liên tục ít nhất 25 - 30 đòn mới hạ được Boss, không thể bị nuke chết giữa đường)
            float maxDamagePerHit = maxHp * 0.04f;
            amount = Mathf.Min(amount, maxDamagePerHit);

            // 2. Áp dụng Giảm Sát Thương theo Phase
            if (damageReductionPercent > 0f)
            {
                amount *= (1f - damageReductionPercent);
            }

            // 3. Kiểm tra ngưỡng Chuyển Phase
            float hpAfter = hp - amount;

            // Ngưỡng chuyển sang Phase 2 (66.6% Máu)
            if (currentPhase == 1 && hpAfter <= maxHp * 0.666f)
            {
                amount = Mathf.Max(0f, hp - (maxHp * 0.666f));
                TransitionToPhase(2);
            }
            // Ngưỡng chuyển sang Phase 3 (33.3% Máu)
            else if (currentPhase == 2 && hpAfter <= maxHp * 0.333f)
            {
                amount = Mathf.Max(0f, hp - (maxHp * 0.333f));
                TransitionToPhase(3);
            }
        }
        else
        {
            // Boss tầng thường
            if (damageReductionPercent > 0f)
            {
                amount *= (1f - damageReductionPercent);
            }
        }

        if (hp <= amount && !isDead)
        {
            if (attackRoutine != null)
            {
                StopCoroutine(attackRoutine);
                attackRoutine = null;
            }
            isAttackingAnimation = false;
            SetMoving(false);
        }

        base.TakeDamage(amount, isCrit, hitDirection);
    }

    {
        currentPhase = nextPhase;

        // Âm thanh sét đánh bùng nổ chuyển phase
        if (AudioManager.Instance != null)
        {
            AudioManager.Instance.PlayLoiPhatSFX();
        }

        if (nextPhase == 2)
        {
            // PHASE 2: Lôi Giáp Bạo Phát
            this.moveSpeed = 3.8f; // Tăng tốc độ chạy áp sát
            this.damageReductionPercent += 0.10f; // Tăng thêm 10% kháng sát thương

            if (CameraShake.Instance != null)
            {
                CameraShake.Instance.TriggerShake(0.5f, 0.3f);
            }

            UpdatePhaseVisuals(2);

            if (GameLogger.Instance != null)
            {
                GameLogger.Instance.Log("⚡ BOSS THIÊN KIẾP BẠO PHÁT: Bước vào PHASE 2 (Lôi Giáp Bất Hoại, Tăng Tốc Độ)!", Color.yellow);
            }
        }
        else if (nextPhase == 3)
        {
            // PHASE 3: Cuồng Nộ Diệt Thế (KHÔNG phóng to kích thước)
            this.moveSpeed = 4.3f; // Lao cực nhanh vào áp sát
            this.damageReductionPercent += 0.10f; // Tăng thêm 10% kháng sát thương

            if (CameraShake.Instance != null)
            {
                CameraShake.Instance.TriggerShake(0.7f, 0.4f);
            }

            UpdatePhaseVisuals(3);

            if (GameLogger.Instance != null)
            {
                GameLogger.Instance.Log("🔥 BOSS THIÊN KIẾP CUỒNG NỘ: Bước vào PHASE 3 (Cuồng Nộ Diệt Thế)!", Color.red);
            }
        }
    }

switchCases.source:
case 1: // Luyện Khí Tầng 15 -> Trúc Cơ Sơ Kỳ
    // Người chơi ở giai đoạn đầu (kiếm lv 2-3, dame ~80-150): Máu vừa tầm 1,800 HP để đánh 15-20 hit
    hp = 1800f;
    dmgReduction = 0.15f; // Kháng 15%
    break;

case 2: // Trúc Cơ Hậu Kỳ -> Kết Đan Sơ Kỳ
    // Người chơi đã mở Vạn Kiếm Quy Tông (20 kiếm chém dồn), kiếm lv 4-6
    hp = 25000f;
    dmgReduction = 0.25f; // Kháng 25%
    break;

case 3: // Kết Đan Hậu Kỳ -> Nguyên Anh Sơ Kỳ
    // Kiếm lv 7-10, buff Tu Lực nhân nhiều lần
    hp = 350000f;
    dmgReduction = 0.35f;
    break;

case 4: // Nguyên Anh Hậu Kỳ -> Hóa Thần Sơ Kỳ
    hp = 4500000f;
    dmgReduction = 0.45f;
    break;

case 5: // Hóa Thần Hậu Kỳ -> Đỉnh Phong
    hp = 50000000f;
    dmgReduction = 0.50f;
    break;

default:
    // Tự động nội suy theo tầng tu vi cụ thể nếu dùng cheat test
    hp = 1800f * Mathf.Pow(2.2f, Mathf.Max(0, (stageIndex - 14) / 3f));
    dmgReduction = Mathf.Clamp(0.15f + (realmTier * 0.08f), 0.15f, 0.55f);
    break;

case 1:
    phaseTextUI.text = "[PHASE 1/3] Kim Cương Thể";
    phaseTextUI.color = new Color(1f, 0.85f, 0.2f); // Cam vàng
    break;

case 2:
    phaseTextUI.text = "[PHASE 2/3] Lôi Giáp Bạo Phát";
    phaseTextUI.color = new Color(0.9f, 0.45f, 1f); // Tím lôi điện
    break;

case 3:
    phaseTextUI.text = "[PHASE 3/3] Cuồng Nộ Diệt Thế";
    phaseTextUI.color = new Color(1f, 0.25f, 0.25f); // Đỏ rực ma lôi
    break;

case 1:
    hpFill.color = new Color(1f, 0.75f, 0.1f); // Cam vàng
    break;

case 2:
    hpFill.color = new Color(0.85f, 0.3f, 1f); // Tím lôi điện
    break;

case 3:
    hpFill.color = new Color(1f, 0.15f, 0.15f); // Đỏ rực
    break;

properties.source:
/// <summary>
/// Kiểm tra xem popup này còn trong thời gian nhận cộng dồn sát thương hay không.
/// </summary>
public bool CanAccumulate => gameObject.activeInHierarchy && accumulateTimer > 0f && disappearTimer > 0.25f;

methods.body:
{
    if (textMesh == null) textMesh = GetComponent<TextMesh>();
    if (textMesh == null) return;

    totalDamage = damageAmount;
    isCritical = isCrit;
    accumulateTimer = ACCUMULATE_WINDOW;
    disappearTimer = DISAPPEAR_TIMER_MAX;
    currentScale = 1.3f;
    transform.localScale = Vector3.one * currentScale;

    UpdateVisuals();
    mainCamera = Camera.main;
}

{
    if (textMesh == null) textMesh = GetComponent<TextMesh>();
    if (textMesh == null) return;

    totalDamage = 0f;
    isCritical = false;
    accumulateTimer = 0f;
    disappearTimer = DISAPPEAR_TIMER_MAX;
    currentScale = 1.4f;
    transform.localScale = Vector3.one * currentScale;

    textMesh.text = text;
    textColor = color;
    textMesh.color = color;
    textMesh.characterSize = size;
    mainCamera = Camera.main;
}

{
    totalDamage += additionalAmount;
    if (isCrit) isCritical = true;

    // Giữ cửa sổ combo đếm ngược tự nhiên (không reset về ban đầu) để các đợt đâm sau sinh ra popup mới nảy lên
    disappearTimer = Mathf.Max(disappearTimer, 0.6f);

    // Hiệu ứng nảy chữ (Punch scale) mỗi khi nhận thêm sát thương
    currentScale = 1.35f;

    UpdateVisuals();
}

{
    if (textMesh == null) return;

    // Thêm dấu '-' đằng trước lượng sát thương theo yêu cầu
    textMesh.text = "-" + Mathf.RoundToInt(totalDamage).ToString();

    // Đòn thường trắng vàng nhạt; crit đỏ cam bạo kích sắc nét, kích cỡ chuẩn Mobile F2P
    if (isCritical)
    {
        textColor = new Color(1f, 0.25f, 0.15f, 1f); // Đỏ cam bạo kích rực rỡ
        textMesh.characterSize = 0.17f;
    }
    else
    {
        textColor = new Color(1f, 0.95f, 0.85f, 0.95f); // Trắng ngà thanh lịch
        textMesh.characterSize = 0.13f;
    }

    textMesh.color = textColor;
}

{
    // Bay lên mượt mà theo phương Y (dùng unscaledDeltaTime để hoạt động cả khi Time.timeScale = 0)
    transform.position += Vector3.up * (moveYSpeed * Time.unscaledDeltaTime);

    // Hiệu ứng nảy chữ đàn hồi (Scale bounce)
    if (currentScale > 1f)
    {
        currentScale = Mathf.MoveTowards(currentScale, 1f, Time.unscaledDeltaTime * 3.5f);
        transform.localScale = Vector3.one * currentScale;
    }

    // Luôn xoay mặt về Camera (Billboarding)
    if (mainCamera != null)
    {
        transform.LookAt(transform.position + mainCamera.transform.rotation * Vector3.forward, mainCamera.transform.rotation * Vector3.up);
    }

    if (accumulateTimer > 0f)
    {
        accumulateTimer -= Time.unscaledDeltaTime;
    }

    disappearTimer -= Time.unscaledDeltaTime;
    if (disappearTimer < 0f)
    {
        // Mờ dần rồi ẩn đi về Object Pool
        float disappearSpeed = 3.5f;
        textColor.a -= disappearSpeed * Time.unscaledDeltaTime;
        if (textMesh != null) textMesh.color = textColor;
        if (textColor.a <= 0f)
        {
            gameObject.SetActive(false);
        }
    }
}

{
    Destroy(gameObject, lifeTime);
}

{
    cam = GetComponent<Camera>();
    AdjustCamera();
}

{
    if (Screen.width != lastWidth || Screen.height != lastHeight)
        AdjustCamera();
}

{
    if (cam == null) return;
    if (Screen.height <= 0 || Screen.width <= 0) return;
    lastWidth = Screen.width;
    lastHeight = Screen.height;
    float currentAspect = (float)lastWidth / lastHeight;
    if (currentAspect < targetAspect)
    {
        float halfFovRadians = defaultFov * Mathf.Deg2Rad * 0.5f;
        cam.fieldOfView = 2f * Mathf.Atan(Mathf.Tan(halfFovRadians) * targetAspect / currentAspect) * Mathf.Rad2Deg;
    }
    else
        cam.fieldOfView = defaultFov;
}

{
    CacheRenderers();
}

{
    if (renderers == null || renderers.Length == 0)
    {
        renderers = GetComponentsInChildren<Renderer>(true);
        if (renderers != null)
        {
            originalColors = new Color[renderers.Length];
            for (int i = 0; i < renderers.Length; i++)
            {
                if (renderers[i] != null && renderers[i].material != null)
                {
                    if (renderers[i].material.HasProperty("_Color"))
                        originalColors[i] = renderers[i].material.color;
                    else if (renderers[i].material.HasProperty("_BaseColor"))
                        originalColors[i] = renderers[i].material.GetColor("_BaseColor");
                    else
                        originalColors[i] = Color.white;
                }
                else
                {
                    originalColors[i] = Color.white;
                }
            }
        }
    }
}

{
    CancelInvoke();
    isDead = false;
    activePopup = null;
    stunTimer = 0f;
}

{
    if (isDead || isBoss) return; // Boss miễn nhiễm hoàn toàn hiệu ứng Choáng!
    stunTimer = Mathf.Max(stunTimer, duration);
    if (animator != null && hasIsMovingParam)
    {
        animator.SetBool("IsMoving", false);
    }
}

    {
        if (isDead || isBoss) return; // Boss miễn nhiễm hoàn toàn hiệu ứng Đẩy lùi!
        direction.y = 0f;
        if (direction.sqrMagnitude > 0.001f)
            direction.Normalize();
        else
            direction = Vector3.forward;

        transform.position += direction * distance;
    }

    {
        SpawnVersion++;
        CancelInvoke();
        maxHp = health;
        hp = health;
        visualHp = health;
        playerTarget = target;
        isBoss = boss;
        damage = boss ? health * 0.2f : Mathf.Max(2f, health * 0.05f); // Sát thương tỉ lệ theo máu (tối thiểu 2)
        isDead = false;
        attackTimer = 0.5f;
        activePopup = null;
        stunTimer = 0f;
        currentRecoilOffset = Vector3.zero;
        scalePunchTimer = 0f;

        if (!hasCapturedScale)
        {
            originalLocalScale = transform.localScale;
            hasCapturedScale = true;
        }
        else
        {
            transform.localScale = originalLocalScale;
        }

        SetupHPBar();

        // Lấy tất cả SkinnedMeshRenderer/MeshRenderer trên Model 3D
        CacheRenderers();
        if (renderers != null && originalColors != null)
        {
            // Phục hồi lại màu ban đầu nếu từng bị Flash trắng
            for (int i = 0; i < renderers.Length; i++)
            {
                if (renderers[i] != null && i < originalColors.Length && renderers[i].material != null)
                {
                    if (renderers[i].material.HasProperty("_Color"))
                        renderers[i].material.color = originalColors[i];
                    else if (renderers[i].material.HasProperty("_BaseColor"))
                        renderers[i].material.SetColor("_BaseColor", originalColors[i]);
                }
            }
        }
        
        if (animator == null) animator = GetComponentInChildren<Animator>();
        hasIsMovingParam = false;
        if (animator != null)
        {
            foreach (var p in animator.parameters)
            {
                if (p.name == "IsMoving") { hasIsMovingParam = true; break; }
            }

            animator.ResetTrigger("Die");
            animator.ResetTrigger("Attack");
            if (hasIsMovingParam) animator.SetBool("IsMoving", false);

            // Đưa Animator về trạng thái ban đầu để tránh bị đông cứng ở thế nằm chết
            animator.Rebind();
            animator.Update(0f);
        }
        
        mainCamera = Camera.main;
    }

    {
        Transform canvasTr = transform.Find("HPCanvas");
        if (canvasTr != null)
        {
            canvasTr.gameObject.SetActive(true);
            canvasTr.localPosition = new Vector3(0, hpBarHeight, 0);
            if (hpFill == null)
            {
                Transform fillTr = canvasTr.Find("HP_BG/HP_Fill");
                if (fillTr != null) hpFill = fillTr.GetComponent<Image>();
            }
            if (hpFill != null)
            {
                hpFill.color = new Color(1f, 0.05f, 0.05f, 1f); // Đỏ tươi rực rỡ, không bị hồng
                RectTransform fillRt = hpFill.GetComponent<RectTransform>();
                fillRt.anchorMax = Vector2.one;
            }
            return;
        }

        CreateHPBar();
    }

    {
        // Tạo Canvas World Space trên đầu quái
        GameObject canvasObj = new GameObject("HPCanvas", typeof(RectTransform), typeof(Canvas));
        canvasObj.transform.SetParent(transform, false);
        canvasObj.transform.localPosition = new Vector3(0, hpBarHeight, 0);
        
        Canvas canvas = canvasObj.GetComponent<Canvas>();
        canvas.renderMode = RenderMode.WorldSpace;
        canvas.sortingOrder = 10;
        RectTransform cRt = canvasObj.GetComponent<RectTransform>();
        cRt.sizeDelta = new Vector2(1.5f, 0.2f); // Kích thước thanh máu

        // Background
        GameObject bgObj = new GameObject("HP_BG", typeof(RectTransform), typeof(Image));
        bgObj.transform.SetParent(canvasObj.transform, false);
        Image bgImg = bgObj.GetComponent<Image>();
        bgImg.color = Color.black;
        RectTransform bgRt = bgObj.GetComponent<RectTransform>();
        bgRt.anchorMin = Vector2.zero; bgRt.anchorMax = Vector2.one;
        bgRt.offsetMin = Vector2.zero; bgRt.offsetMax = Vector2.zero;

        // Fill
        GameObject fillObj = new GameObject("HP_Fill", typeof(RectTransform), typeof(Image));
        fillObj.transform.SetParent(bgObj.transform, false);
        hpFill = fillObj.GetComponent<Image>();
        hpFill.color = new Color(1f, 0.05f, 0.05f, 1f); // Đỏ tươi rực rỡ, không bị hồng
        // Không dùng Filled vì thiếu Sprite gốc sẽ lỗi, dùng Anchor thay thế
        RectTransform fillRt = fillObj.GetComponent<RectTransform>();
        fillRt.anchorMin = Vector2.zero; 
        fillRt.anchorMax = Vector2.one;
        fillRt.offsetMin = Vector2.zero; 
        fillRt.offsetMax = Vector2.zero;
    }

    {
        UpdateHpBar();
        UpdateFlashEffect();
        UpdateGameFeelRecoil();

        // Xử lý Choáng (Stun): Quái vật đứng im hoàn toàn, không di chuyển và không đánh
        if (stunTimer > 0f)
        {
            stunTimer -= Time.deltaTime;
            if (animator != null && hasIsMovingParam) animator.SetBool("IsMoving", false);
            return;
        }

        UpdateMovementAndCombat();
    }

{
    // Smooth HP Bar (Game Feel)
    if (hpFill != null)
    {
        visualHp = Mathf.Lerp(visualHp, hp, Time.deltaTime * 10f);
        float fillRatio = Mathf.Clamp01(visualHp / maxHp);
        RectTransform fillRt = hpFill.GetComponent<RectTransform>();
        fillRt.anchorMax = new Vector2(fillRatio, 1f);
        
        // Xoay thanh máu luôn nhìn về Camera chính
        if (mainCamera != null)
        {
            hpFill.transform.parent.parent.LookAt(hpFill.transform.parent.parent.position + mainCamera.transform.rotation * Vector3.forward, mainCamera.transform.rotation * Vector3.up);
        }
    }
}

    {
        if (renderers == null || originalColors == null) return;

        // Đổi màu giật cục (Flash)
        if (flashTimer > 0)
        {
            flashTimer -= Time.deltaTime;
            if (flashTimer <= 0)
            {
                // Trả lại màu gốc
                for (int i = 0; i < renderers.Length; i++)
                {
                    if (renderers[i] != null && i < originalColors.Length && renderers[i].material != null)
                    {
                        if (renderers[i].material.HasProperty("_Color"))
                            renderers[i].material.color = originalColors[i];
                        else if (renderers[i].material.HasProperty("_BaseColor"))
                            renderers[i].material.SetColor("_BaseColor", originalColors[i]);
                    }
                }
            }
        }
    }

    {
        // 1. Phục hồi lò xo đẩy lùi đàn hồi (Elastic Spring-Back)
        if (currentRecoilOffset.sqrMagnitude > 0.0001f)
        {
            transform.position -= currentRecoilOffset;
            currentRecoilOffset = Vector3.Lerp(currentRecoilOffset, Vector3.zero, Time.deltaTime * 16f);
            transform.position += currentRecoilOffset;
        }
        else if (currentRecoilOffset != Vector3.zero)
        {
            transform.position -= currentRecoilOffset;
            currentRecoilOffset = Vector3.zero;
        }

        // 2. Phục hồi Squash & Stretch (Co giãn mô hình khi trúng đòn)
        if (scalePunchTimer > 0f)
        {
            scalePunchTimer -= Time.deltaTime;
            float progress = Mathf.Clamp01(scalePunchTimer / 0.12f);
            Vector3 targetPunchScale = new Vector3(
                originalLocalScale.x * (1f + 0.15f * progress),
                originalLocalScale.y * (1f - 0.20f * progress),
                originalLocalScale.z * (1f + 0.15f * progress)
            );
            transform.localScale = targetPunchScale;
        }
        else if (transform.localScale != originalLocalScale)
        {
            transform.localScale = Vector3.Lerp(transform.localScale, originalLocalScale, Time.deltaTime * 20f);
            if ((transform.localScale - originalLocalScale).sqrMagnitude < 0.0001f)
            {
                transform.localScale = originalLocalScale;
            }
        }
    }

    {
        if (playerTarget == null || isDead) return;

        // BỎ QUA TRỤC Y khi tính khoảng cách (để tránh lỗi quái không bao giờ tới gần vì độ cao 3D)
        float dist = Vector2.Distance(new Vector2(transform.position.x, transform.position.z), new Vector2(playerTarget.position.x, playerTarget.position.z));
        Vector3 targetPos = new Vector3(playerTarget.position.x, transform.position.y, playerTarget.position.z);
        
        // Xoay mượt về phía Player
        Vector3 dir = (targetPos - transform.position).normalized;
        if (dir.sqrMagnitude > 0.001f)
        {
            Quaternion targetRot = Quaternion.LookRotation(dir);
            transform.rotation = Quaternion.RotateTowards(transform.rotation, targetRot, 500f * Time.deltaTime);
        }

        if (dist > attackRange)
        {
            // Cả quái thường lẫn Boss đều di chuyển tiến lại gần sát người chơi
            float formationSlow = isBoss && FormationService.Instance != null ? FormationService.Instance.BossSpeedMultiplier : 1f;
            transform.position = Vector3.MoveTowards(transform.position, targetPos, moveSpeed * formationSlow * Time.deltaTime);
            
            if (animator != null && hasIsMovingParam) animator.SetBool("IsMoving", true);
        }
        else
        {
            // Đã vào tầm đánh cận chiến sát Player -> Dừng lại và tấn công
            if (animator != null && hasIsMovingParam) animator.SetBool("IsMoving", false);
            
            if (attackTimer > 0)
            {
                attackTimer -= Time.deltaTime;
            }
            else
            {
                attackTimer = isBoss ? 1.5f : (1f / attackSpeed);
                
                if (animator != null) animator.SetTrigger("Attack"); // Kích hoạt Anim Đánh
                
                if (!isBoss && HitVFXManager.Instance != null)
                {
                    Vector3 swipePos = transform.position + transform.forward * 0.9f + Vector3.up * 1f;
                    HitVFXManager.Instance.SpawnEnemyAttackSwipe(swipePos, transform.forward);
                }

                if (CombatManager.Instance != null)
                {
                    CombatManager.Instance.DamagePlayer(damage, isBoss);
                }
            }
        }
    }

    {
        hp -= amount;
        
        // Game Feel 1: Flash trắng cho toàn bộ Model 3D
        flashTimer = 0.1f;
        if (renderers != null)
        {
            foreach (var r in renderers)
            {
                if (r != null && r.material != null)
                {
                    if (r.material.HasProperty("_Color"))
                        r.material.color = Color.white;
