    if (stageIndex < 3) { start = 0; count = 3; }
    else if (stageIndex < 8) { start = 3; count = 5; }
    else if (stageIndex < 13) { start = 8; count = 5; }
    else { start = 13; count = 2; }
    return Mathf.Clamp01((stageIndex - start + stageFraction) / count);
}

{
