    // --- TEST 10: KIỂM THỬ BA BỔ SUNG GAMEPLAY (KIẾM PHÁP, HỘ THỂ BOSS 10, KỲ NGỘ 2 LỰA CHỌN) ---
    total++;
    GameObject tempChoicesGo = null;
