    foreach (Transform child in panel)
    {
        if (child != scroll && child.name != "Title" && child.name != "CloseButton" && child.name != "SwipeHandle")
            toMove.Add(child);
    }
    foreach (Transform child in toMove)
        child.SetParent(content, false);

    return content;
}

