private static Font DefaultFont
{
    get
    {
        var f = UiTextStyle.BodyFont;
        if (f != null) return f;
        f = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        if (f != null) return f;
        return Resources.GetBuiltinResource<Font>("Arial.ttf");
    }
}

