{
    Debug.Log("🚀 [SkillTest] Bắt đầu kiểm thử toàn diện 4 Tuyệt Kỹ: Chưởng Ấn, Lôi Phạt, Âm Dương Trận, Vạn Kiếm Quy Tông!");

    // 1. Chờ Arena tải xong và bỏ qua Main Menu nếu có
