        {
            realmMult = 1 + Mathf.Clamp((int)CultivationManager.Instance.CurrentRealm, 0, 8) * 2;
        }
        EconomyManager.Instance.AddLinhThach(item.rewardLinhThach * realmMult);
    }

    // 2. Thưởng Cơ Duyên
