properties.source:
public static LootRewardService Instance
{
    get
    {
        if (_instance == null)
        {
            _instance = UnityEngine.Object.FindAnyObjectByType<LootRewardService>();
        }
        return _instance;
    }
    private set => _instance = value;
}

methods.body:
{
    if (_instance != null && _instance != this)
    {
        Destroy(this);
        return;
    }
    _instance = this;
}

{
    if (_instance == this) _instance = null;
}

{
    RealmId currentRealm = RealmId.LuyenKhi;
    int subLevel = 1;

    if (CultivationManager.Instance != null)
    {
        currentRealm = CultivationManager.Instance.CurrentRealm;
        subLevel = CultivationManager.Instance.CurrentSubLevel;
    }

    if (isBoss)
    {
        HandleBossLoot(currentRealm, subLevel, combatStage);
    }
    else
    {
        HandleRegularMonsterLoot(currentRealm, subLevel, combatStage);
    }
}

{
    // A. ROLL RƠI PHI KIẾM (Tối đa 1 kiếm trên mỗi quái thường)
    RollSwordDrop(realm, subLevel);

    // B. ROLL RƠI THẢO DƯỢC (Chỉ rơi từ Luyện Khí 7 trở đi)
    if (FeatureUnlockService.Instance == null || FeatureUnlockService.Instance.CanDropHerbs())
    {
        RollHerbDrop(realm, subLevel);
    }

    // C. ROLL RƠI QUẶNG TINH THIẾT (Chỉ rơi từ Trúc Cơ 1 trở đi)
    if (FeatureUnlockService.Instance == null || FeatureUnlockService.Instance.CanDropOre())
    {
        RollOreDrop(realm, subLevel);
    }
}

{
    float p1 = 0f, p2 = 0f, p3 = 0f, p4 = 0f;

    if (realm == RealmId.LuyenKhi)
    {
        if (subLevel <= 3)
        {
            p1 = 0.24f; // 24% Lv1
        }
        else if (subLevel <= 6)
        {
            p1 = 0.22f; // 22% Lv1
            p2 = 0.01f; // 1% Lv2
        }
        else
        {
            p1 = 0.19f; // 19% Lv1
            p2 = 0.02f; // 2% Lv2
        }
    }
    else if (realm == RealmId.TrucCo)
    {
        p1 = 0.13f;
        p2 = 0.04f;
        p3 = 0.005f;
    }
    else if (realm == RealmId.KimDan)
    {
        p1 = 0.10f;
        p2 = 0.05f;
        p3 = 0.01f;
    }
    else if (realm == RealmId.NguyenAnh)
    {
        p1 = 0.08f;
        p2 = 0.06f;
        p3 = 0.02f;
        p4 = 0.002f;
    }
    else // Hóa Thần trở lên
    {
        p1 = 0.06f;
        p2 = 0.06f;
        p3 = 0.03f;
        p4 = 0.005f;
    }

    float dropChance = Mathf.Clamp01((p1 + p2 + p3 + p4) * (1f + DaoAnProgressionService.Bonus(DaoAnEffect.SwordDropRate)));
    float roll = UnityEngine.Random.value;
    if (roll >= dropChance) return;

    // Redistribute only the tiers already present in this realm's drop table.
    float tierMultiplier = 1f + DaoAnProgressionService.Bonus(DaoAnEffect.SwordTierWeight);
    p2 *= tierMultiplier;
    p3 *= tierMultiplier;
    p4 *= tierMultiplier;
    float tierRoll = roll / dropChance * (p1 + p2 + p3 + p4);
    int droppedLevel = 1;
    if (tierRoll < p4) droppedLevel = 4;
    else if (tierRoll < p4 + p3) droppedLevel = 3;
    else if (tierRoll < p4 + p3 + p2) droppedLevel = 2;
    DeliverSword(droppedLevel, isMonsterDrop: true);
}

{
    if (AlchemyService.Instance == null) return;

    float pLinhChi = 0f;
    float pNgungKhi = 0f;
    float pTuyetLien = 0f;

    if (realm == RealmId.LuyenKhi)
    {
        if (subLevel >= 7)
        {
            pLinhChi = 0.08f;
            pNgungKhi = 0.04f;
            pTuyetLien = 0.004f;
        }
    }
    else if (realm == RealmId.TrucCo)
    {
        pLinhChi = 0.08f;
        pNgungKhi = 0.05f;
        pTuyetLien = 0.008f;
    }
    else if (realm == RealmId.KimDan)
    {
        pLinhChi = 0.07f;
        pNgungKhi = 0.05f;
        pTuyetLien = 0.01f;
    }
    else if (realm == RealmId.NguyenAnh)
    {
        pLinhChi = 0.07f;
        pNgungKhi = 0.06f;
        pTuyetLien = 0.015f;
    }
    else // Hóa Thần trở lên
    {
        pLinhChi = 0.06f;
        pNgungKhi = 0.06f;
        pTuyetLien = 0.02f;
    }

    float multiplier = 1f + DaoAnProgressionService.Bonus(DaoAnEffect.HerbDropRate);
    if (pLinhChi > 0 && UnityEngine.Random.value < Mathf.Clamp01(pLinhChi * multiplier))
    {
        AlchemyService.Instance.AddHerb(0, 1);
        GameLogger.Instance?.Log("Thu thập: 1 Linh Chi", new Color(0.5f, 1f, 0.5f));
    }

    if (pNgungKhi > 0 && UnityEngine.Random.value < Mathf.Clamp01(pNgungKhi * multiplier))
    {
        AlchemyService.Instance.AddHerb(1, 1);
        GameLogger.Instance?.Log("Thu thập: 1 Cỏ Ngưng Khí", new Color(0.2f, 0.9f, 0.6f));
    }

    if (pTuyetLien > 0 && UnityEngine.Random.value < Mathf.Clamp01(pTuyetLien * multiplier))
    {
        AlchemyService.Instance.AddHerb(2, 1);
        GameLogger.Instance?.Log("Thu thập quý: 1 Tuyết Liên Tinh Khiết!", Color.cyan);
    }
}

{
    if (ArtifactService.Instance == null) return;

    float pOre = 0f;

    if (realm == RealmId.TrucCo) pOre = 0.015f;
    else if (realm == RealmId.KimDan) pOre = 0.02f;
    else if (realm == RealmId.NguyenAnh) pOre = 0.025f;
    else if (realm >= RealmId.HoaThan) pOre = 0.03f;

    float multiplier = 1f + DaoAnProgressionService.Bonus(DaoAnEffect.OreDropRate);
    if (pOre > 0 && UnityEngine.Random.value < Mathf.Clamp01(pOre * multiplier))
    {
        ArtifactService.Instance.AddOre(1);
        GameLogger.Instance?.Log("Khai khoáng: 1 Quặng Tinh Thiết", new Color(1f, 0.75f, 0.2f));
    }
}

{
    // 1. Boss luôn rớt 1 Kiếm Phôi chất lượng cao (Cấp 2 hoặc Cấp 3)
    int bossSwordLevel = 1;
    if (realm == RealmId.LuyenKhi)
    {
        bossSwordLevel = (subLevel >= 7) ? 2 : 1;
    }
    else if (realm == RealmId.TrucCo)
    {
        bossSwordLevel = 2;
    }
    else
    {
        bossSwordLevel = (UnityEngine.Random.value < 0.4f) ? 3 : 2;
    }
    DeliverSword(bossSwordLevel, isMonsterDrop: true);

    // 2. Dược liệu Boss: Chỉ rơi khi Luyện Đan đã mở (LK7+)
    if (FeatureUnlockService.Instance == null || FeatureUnlockService.Instance.CanDropHerbs())
    {
        if (AlchemyService.Instance != null)
        {
            int lc = 2 + combatStage / 20 + Mathf.FloorToInt(DaoAnProgressionService.Bonus(DaoAnEffect.BossHerbBonus));
            int nk = 1 + combatStage / 30;
            int tl = 1 + combatStage / 40;
            AlchemyService.Instance.AddHerb(0, lc);
            AlchemyService.Instance.AddHerb(1, nk);
            AlchemyService.Instance.AddHerb(2, tl);
            GameLogger.Instance?.Log($"Yêu Vương rơi bảo vật: +{lc} Linh Chi, +{nk} Cỏ NK, +{tl} Tuyết Liên!", Color.green);
        }
    }

    // 3. Quặng Boss: Chỉ rơi khi Pháp Trận đã mở (Trúc Cơ 1+)
    if (FeatureUnlockService.Instance == null || FeatureUnlockService.Instance.CanDropOre())
    {
        if (ArtifactService.Instance != null)
        {
            int oreAmount = 2 + combatStage / 10 + Mathf.FloorToInt(DaoAnProgressionService.Bonus(DaoAnEffect.BossOreDrop));
            ArtifactService.Instance.AddOre(oreAmount);
            GameLogger.Instance?.Log($"Yêu Vương rơi quặng quý: +{oreAmount} Quặng Tinh Thiết!", new Color(1f, 0.8f, 0.2f));
        }
    }
}

{
    string swordName = DismantleService.GetSwordDisplayName(level);

    if (StorageManager.Instance != null)
    {
        StorageManager.Instance.HandleSwordDrop(level, isMonsterDrop);
    }
    else if (MergeManager.Instance != null)
    {
        bool added = MergeManager.Instance.TryAddSword(level);
        if (added && isMonsterDrop)
        {
            FeatureUnlockService.Instance?.OnMonsterSwordAcquired(level);
        }
    }

    GameLogger.Instance?.Log($"Trảm quái nhặt được: {swordName}!", Color.yellow);
}

{
    if (Instance != null && Instance != this)
    {
        Destroy(this);
        return;
    }
    Instance = this;
}

{
    cachedCamera = Camera.main;

    if (mapChunks == null)
    {
        mapChunks = new List<Transform>();
    }
    mapChunks.RemoveAll(c => c == null);

    // 1. Tự động nhận diện kích thước Terrain nếu có
    if (mapChunks.Count > 0 && mapChunks[0] != null)
    {
        Terrain terrain = mapChunks[0].GetComponent<Terrain>();
        if (terrain != null && terrain.terrainData != null)
        {
            chunkLength = terrain.terrainData.size.z;
            Debug.Log($"[MapScroller] Nhận diện chunkLength theo Terrain: {chunkLength}m");
        }
    }

    // 2. BẢO ĐẢM VÔ TẬN: Nếu chỉ có 1 chunk duy nhất trong Scene, tự động Clone chunk thứ 2
    // để tạo vòng lặp vô tận cuốn chiếu (không bao giờ lộ khoảng trống hư không)
    if (mapChunks.Count == 1 && mapChunks[0] != null)
    {
        GameObject origObj = mapChunks[0].gameObject;
        GameObject cloneObj = Instantiate(origObj, origObj.transform.parent);
        cloneObj.name = origObj.name + "_LoopClone";

        // Chia sẻ chung asset TerrainData để không tốn thêm bộ nhớ
        Terrain origTerrain = origObj.GetComponent<Terrain>();
        Terrain cloneTerrain = cloneObj.GetComponent<Terrain>();
        if (origTerrain != null && cloneTerrain != null)
        {
            cloneTerrain.terrainData = origTerrain.terrainData;
        }

        Vector3 clonePos = mapChunks[0].position;
        clonePos.z += chunkLength;
        cloneObj.transform.position = clonePos;

        mapChunks.Add(cloneObj.transform);
        Debug.Log($"[MapScroller] Đã tự động tạo Terrain Chunk thứ 2 tại Z = {clonePos.z} để cuộn vô tận không vết ghép.");
    }

    // 3. Sắp xếp lại toàn bộ các chunk theo thứ tự nối đuôi liên tục
    if (mapChunks.Count > 0 && mapChunks[0] != null)
    {
        float startZ = mapChunks[0].position.z;
        for (int i = 0; i < mapChunks.Count; i++)
        {
            if (mapChunks[i] != null)
            {
                Vector3 pos = mapChunks[i].position;
                pos.z = startZ + (i * chunkLength);
                mapChunks[i].position = pos;
            }
        }
    }
}

{
    if (!isMoving || mapChunks == null || mapChunks.Count == 0) return;

    float delta = scrollSpeed * Time.deltaTime;
    float camZ = cachedCamera != null ? cachedCamera.transform.position.z : 0f;

    // 1. Di chuyển toàn bộ các chunk về phía sau theo tốc độ bước chân
    for (int i = 0; i < mapChunks.Count; i++)
    {
        if (mapChunks[i] != null)
        {
            mapChunks[i].Translate(Vector3.back * delta, Space.World);
        }
    }

    // 2. Kiểm tra tái sinh chunk (Recycle) khi mép trước của chunk đã trôi hẳn ra sau lưng Camera
    for (int i = 0; i < mapChunks.Count; i++)
    {
        Transform chunk = mapChunks[i];
        if (chunk == null) continue;

        // Mép trước của chunk địa hình nằm tại (chunk.position.z + chunkLength)
        float frontEdgeZ = chunk.position.z + chunkLength;

        // Khi toàn bộ chunk đã vượt qua sau lưng camera ít nhất 30 mét
        if (frontEdgeZ < camZ - 30f)
        {
            // Tìm vị trí chunk xa nhất ở phía trước
            float maxZ = float.MinValue;
            for (int j = 0; j < mapChunks.Count; j++)
            {
                if (mapChunks[j] != null && mapChunks[j] != chunk)
                {
                    if (mapChunks[j].position.z > maxZ)
                    {
                        maxZ = mapChunks[j].position.z;
                    }
                }
            }

            if (maxZ > float.MinValue)
            {
                Vector3 newPos = chunk.position;
                // Bắt khớp chính xác vào mép trước của chunk xa nhất
                newPos.z = maxZ + chunkLength;
                chunk.position = newPos;
            }
        }
    }
}

{
    isMoving = false;
    if (CombatManager.Instance != null && CombatManager.Instance.playerAnimator != null)
    {
        CombatManager.Instance.playerAnimator.SetBool("IsMoving", false);
    }
}

{
    isMoving = true;
    if (CombatManager.Instance != null && CombatManager.Instance.playerAnimator != null)
    {
        CombatManager.Instance.playerAnimator.SetBool("IsMoving", true);
    }
}

{
    ResumeMoving();
}

{
    Color randomColor = new Color(Random.Range(0.6f, 1f), Random.Range(0.6f, 1f), Random.Range(0.6f, 1f));
    foreach (Transform chunk in mapChunks)
    {
        if (chunk == null) continue;
        Renderer r = chunk.GetComponentInChildren<Renderer>();
        if (r != null && r.material != null)
        {
            r.material.color = randomColor;
        }
    }
}

properties.source:
public int EquippedCount
{
    get
    {
        if (equipPanel == null) return 0;
        int count = 0;
        foreach (Transform slot in equipPanel)
        {
            if (slot != null && slot.GetComponentInChildren<MergeItem>() != null) count++;
        }
        return count;
    }
}

methods.body:
{
    if (Instance != null && Instance != this)
    {
        Destroy(this);
        return;
    }
    Instance = this;
}

{
    if (SwordLoadoutService.Instance != null)
        SwordLoadoutService.Instance.OnCapacityChanged += HandleCapacityChanged;
    // Kiểm tra trễ 0.5s. Nếu DataManager.LoadCurrentGame KHÔNG được gọi (do test trực tiếp Scene)
    // hoặc load bị lỗi, thì chúng ta sẽ tự tạo 1 cây kiếm mặc định để không bị kẹt game.
    Invoke(nameof(FailsafeCheckSword), 0.5f);
    
    OnEquipChanged();
}

{
    if (SwordLoadoutService.Instance != null)
        SwordLoadoutService.Instance.OnCapacityChanged -= HandleCapacityChanged;
}

    {
        if (equipPanel == null) return;
        
        bool hasSword = false;
        foreach (Transform equipSlot in equipPanel)
        {
            if (equipSlot.GetComponentInChildren<MergeItem>() != null)
            {
                hasSword = true;
                break;
            }
        }

        if (!hasSword && mergeItemPrefab != null && equipPanel.childCount > 0)
        {
            Debug.Log("[MergeManager] Failsafe: Không tìm thấy kiếm nào sau khi load. Tự động tạo 1 phôi kiếm cấp 1.");
            Transform firstEquipSlot = equipPanel.GetChild(0);
            GameObject newItem = Instantiate(mergeItemPrefab, firstEquipSlot);
            newItem.GetComponent<MergeItem>().SetLevel(1);
            OnEquipChanged();
        }
    }

    {
        if (inventoryPages == null || inventoryPages.Length == 0 || mergeItemPrefab == null) return;
        
        // Thu thập phôi ở kho; kiếm đang trang bị giữ nguyên ô và được nâng cấp từ phôi kho.
        var allItems = new System.Collections.Generic.List<MergeItem>();
        foreach (Transform page in inventoryPages)
        {
            foreach (Transform slot in page)
            {
                MergeItem item = slot.GetComponentInChildren<MergeItem>();
                if (item != null) allItems.Add(item);
            }
        }

        // 2. Thống kê số lượng phôi theo từng cấp
        int[] counts = new int[9]; // Mảng đếm phôi từ level 1 -> 8
        foreach (var item in allItems)
        {
            counts[Mathf.Clamp(item.level, 1, 8)] += Mathf.Max(1, item.currentPieces);
            item.transform.SetParent(null); // Rời khỏi slot ngay lập tức để tạo chỗ trống
            Destroy(item.gameObject); // Xóa hết item cũ (sẽ thực thi cuối frame)
        }

        // 3. Xử lý gộp từ cấp thấp lên cấp cao
        int totalUpgrades = 0;
        for (int L = 1; L < 8; L++)
        {
            // Ưu tiên nâng kiếm đang trang bị ở cấp hiện tại; sau đó mới ghép phần kho còn lại.
            if (equipPanel != null)
            {
                int maxCap = SwordLoadoutService.Instance != null 
                    ? SwordLoadoutService.Instance.GetCurrentCapacity() 
                    : equipPanel.childCount;
                foreach (Transform slot in equipPanel)
                {
                    if (slot.GetSiblingIndex() >= maxCap) continue;
                    MergeItem equipped = slot.GetComponentInChildren<MergeItem>();
                    if (equipped == null || equipped.level != L) continue;
                    int requiredPieces = equipped.GetRequiredPieces();
                    int needed = Mathf.Max(0, requiredPieces - equipped.currentPieces);
                    if (counts[L] < needed) continue;
                    counts[L] -= needed;
                    counts[L] += Mathf.Max(0, equipped.currentPieces - requiredPieces);
                    equipped.currentPieces = 1;
                    equipped.level++;
                    equipped.UpdateUI();
                    AchievementManager.Instance?.OnSwordMerged(equipped.level);
                    totalUpgrades++;
                }
            }
            int required = GetRequiredPiecesForLevel(L);
            int upgrades = counts[L] / required;
            totalUpgrades += upgrades;
            counts[L] = counts[L] % required; // Phôi lẻ còn dư
            counts[L + 1] += upgrades;
        }

        // 4. Sinh lại các thanh kiếm theo số lượng đã tính toán
        for (int L = 1; L <= 8; L++)
        {
            if (counts[L] > 0)
            {
                // Vì mỗi item có thể chứa nhiều phôi (chưa đủ để lên cấp)
                // Ta chỉ cần sinh 1 item cho mỗi cấp, và gán currentPieces = counts[L]
                TryAddSwordWithPieces(L, counts[L]);
            }
        }
        
        // 5. Sắp xếp lại kho sau khi ghép
        SortInventory();
        OnEquipChanged();

        if (totalUpgrades > 0 && AudioManager.Instance != null)
        {
            AudioManager.Instance.PlayMergeSwordSFX();
        }

        Debug.Log("[Merge] Đã ghép nhanh tuân thủ tỷ lệ thành công!");
    }

