{
    List<string> parts = new List<string>();
    if (rewardLinhThach > 0) parts.Add($"+{rewardLinhThach:F0} LT");
    if (rewardCoDuyen > 0) parts.Add($"Cơ Duyên +{rewardCoDuyen}");

