        parts.Add($"{dName} x{rewardDanDuocAmount}");
    }

    if (rewardSwordLevel > 0)
    {
        parts.Add($"Kiếm Cấp {rewardSwordLevel}");
    }

    return string.Join(" | ", parts);
}

