        {
            elapsed += Time.unscaledDeltaTime;
            float t = Mathf.Clamp01(elapsed / duration);
            modalBox.localScale = Vector3.Lerp(startScale, Vector3.one, Mathf.SmoothStep(0f, 1f, t));
