        if (CombatManager.Instance != null)
        {
            float hp = CombatManager.Instance.playerCurrentHp;
            float maxHp = CombatManager.Instance.playerMaxHp;
            if (txtHp != null) txtHp.text = $"Sinh Lực: <color=#55FF55>{Mathf.Ceil(hp):N0} / {maxHp:N0}</color>";
        }

        if (SkillManager.Instance != null)
        {
            float mp = SkillManager.Instance.currentLinhLuc;
            float maxMp = SkillManager.Instance.maxLinhLuc;
            float regen = SkillManager.Instance.linhLucRegenRate;
            if (txtMp != null) txtMp.text = $"Linh Lực: <color=#66B2FF>{mp:F0} / {maxMp:F0}</color> (+{regen:F1}/s hồi phục)";
        }

        if (CultivationManager.Instance != null)
        {
            float mult = CultivationManager.Instance.permanentStatMultiplier;
            float bonus = (mult - 1f) * 100f;
            if (txtMultiplier != null) txtMultiplier.text = $"Khí Tức Tiên Thiên: <color=#FFDD44>+{bonus:F1}%</color> (Hệ số x{mult:F2})";
        }

        // 3. PHI KIẾM ĐANG XUẤT TRẬN
        if (MergeManager.Instance != null && MergeManager.Instance.equipPanel != null)
        {
            int equippedCount = 0;
            float totalDamage = 0f;
            for (int i = 0; i < 4; i++)
            {
                if (i < MergeManager.Instance.equipPanel.childCount)
                {
                    Transform slot = MergeManager.Instance.equipPanel.GetChild(i);
                    MergeItem item = slot.GetComponentInChildren<MergeItem>();
                    if (item != null && item.level > 0)
                    {
                        equippedCount++;
                        totalDamage += FlyingSword.CalculateBaseDamage(item.level);
                    }
                }
            }

            if (txtEquipSwords != null)
            {
                txtEquipSwords.text = $"Phi Kiếm Đang Xuất Trận: <color=#FFE666>{equippedCount}/4 Thanh</color> (Tổng Căn Cơ: {totalDamage:N0} Dame)";
            }
        }

        // 4. CHỈ SỐ CÔNG PHÁP NÂNG CẤP (Thứ tự: Kiếm Ý, Linh Lực, Tụ Linh, Thần Thức)
        int lvlKY = 1;
        int lvlLL = 1;
        int lvlTL = 1;
        int lvlTT = 1;

        float valKY = 15f;
        float valTL = 15f;
        float valTT = 12f;
        float maxMpVal = 100f;
        float regenMpVal = 10f;

        if (UpgradeManager.Instance != null)
        {
            lvlKY = UpgradeManager.Instance.kiemYLevel;
            lvlLL = UpgradeManager.Instance.linhLucLevel;
            lvlTL = UpgradeManager.Instance.tuLinhLevel;
            lvlTT = UpgradeManager.Instance.thanThucLevel;

            valKY = UpgradeManager.Instance.GetKiemYValue();
            if (valKY <= 0) valKY = 10f + (lvlKY * 5f);

            valTL = UpgradeManager.Instance.GetTuLinhValue();
            if (valTL <= 0) valTL = 10f + (lvlTL * 5f);

            valTT = UpgradeManager.Instance.GetThanThucValue();
            if (valTT <= 0) valTT = 10f + (lvlTT * 2f);
        }

        if (SkillManager.Instance != null)
        {
            maxMpVal = SkillManager.Instance.maxLinhLuc;
            regenMpVal = SkillManager.Instance.linhLucRegenRate;
        }

        // Hiển thị đầy đủ Tên, Cấp và Chỉ số thực tế
        if (txtUpgradeKiemY != null)
            txtUpgradeKiemY.text = $"• <color=#FF8866>Kiếm Ý</color>: Cấp {lvlKY} · Chỉ số: <color=#FFE666>+{valKY:F1} Sát thương Kiếm</color>";

        if (txtUpgradeLinhLuc != null)
            txtUpgradeLinhLuc.text = $"• <color=#66CCFF>Linh Lực</color>: Cấp {lvlLL} · Chỉ số: <color=#66CCFF>{maxMpVal:F0} MP</color> (+{regenMpVal:F1}/s hồi phục)";

        if (txtUpgradeTuLinh != null)
            txtUpgradeTuLinh.text = $"• <color=#88FF88>Tụ Linh</color>: Cấp {lvlTL} · Chỉ số: <color=#88FF88>+{valTL:F1}% Thu nạp Linh Thạch</color>";

        if (txtUpgradeThanThuc != null)
            txtUpgradeThanThuc.text = $"• <color=#CC88FF>Thần Thức</color>: Cấp {lvlTT} · Chỉ số: <color=#CC88FF>+{valTT:F1}% Tốc độ xuất chiêu</color>";
    }

    {
        if (canvasGroup == null) canvasGroup = GetComponent<CanvasGroup>();
        if (modalBox == null) modalBox = transform.Find("ModalBox") as RectTransform;

        float duration = 0.2f;
        float elapsed = 0f;
        Vector3 baseScale = Vector3.one;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / duration);

            // Pop bounce nhẹ nhàng
            float scale = Mathf.Lerp(0.85f, 1.0f, Mathf.Sin(t * Mathf.PI * 0.5f));
            if (modalBox != null) modalBox.localScale = baseScale * scale;
            if (canvasGroup != null) canvasGroup.alpha = t;
            yield return null;
        }

        if (modalBox != null) modalBox.localScale = baseScale;
        if (canvasGroup != null) canvasGroup.alpha = 1f;
        animRoutine = null;
    }

    {
        if (canvasGroup == null) canvasGroup = GetComponent<CanvasGroup>();
        if (modalBox == null) modalBox = transform.Find("ModalBox") as RectTransform;

        float duration = 0.15f;
        float elapsed = 0f;
        Vector3 baseScale = Vector3.one;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / duration);

            float scale = Mathf.Lerp(1.0f, 0.9f, t);
            if (modalBox != null) modalBox.localScale = baseScale * scale;
            if (canvasGroup != null) canvasGroup.alpha = 1f - t;
            yield return null;
        }

        if (canvasGroup != null) canvasGroup.alpha = 0f;
        gameObject.SetActive(false);
        animRoutine = null;
    }

    {
        frameImage = GetComponent<Image>();
        if (frameImage != null)
        {
            originalColor = frameImage.color;
            hoverColor = new Color(originalColor.r * 1.25f, originalColor.g * 1.25f, originalColor.b * 1.35f, originalColor.a);
        }

        // Đảm bảo có Button hoặc nhận diện được Raycast
        if (frameImage != null)
        {
            frameImage.raycastTarget = true;
        }
    }

{
    CharacterDetailModalUI.Open();
}

{
    if (frameImage != null)
    {
        frameImage.color = hoverColor;
    }
}

{
    if (frameImage != null)
    {
        frameImage.color = originalColor;
    }
}

{
    if (txt == null) txt = GetComponent<Text>();
    if (EconomyManager.Instance != null)
    {
        EconomyManager.Instance.OnCoDuyenChanged += UpdateUI;
        UpdateUI(EconomyManager.Instance.currentCoDuyen);
    }
}

{
    if (EconomyManager.Instance != null)
    {
        EconomyManager.Instance.OnCoDuyenChanged -= UpdateUI;
    }
}

{
    if (txt != null)
    {
        txt.text = coDuyen.ToString();
    }
}

{
    if (Instance != null && Instance != this) { Destroy(this); return; }
    Instance = this;
    rectTransform = GetComponent<RectTransform>();
}

{
    if (rectTransform != null)
    {
        expandedPos = rectTransform.anchoredPosition;
        float width = rectTransform.sizeDelta.x > 0 ? rectTransform.sizeDelta.x : 260f;
        collapsedPos = new Vector2(-width + 32f, expandedPos.y);
    }
    BuildToggleButtonIfNeeded();
}

{
    if (transform.Find("BtnQuestToggle") != null) return;

    var btnObj = new GameObject("BtnQuestToggle", typeof(RectTransform), typeof(Image), typeof(Button));
    btnObj.transform.SetParent(transform, false);

    var rt = btnObj.GetComponent<RectTransform>();
    rt.anchorMin = new Vector2(1f, 0f);
    rt.anchorMax = new Vector2(1f, 1f);
    rt.pivot = new Vector2(0f, 0.5f);
    rt.anchoredPosition = new Vector2(0f, 0f);
    rt.sizeDelta = new Vector2(26f, 0f);

    btnObj.GetComponent<Image>().color = new Color(0.11f, 0.15f, 0.22f, 0.95f);

    var txtObj = new GameObject("ArrowText", typeof(RectTransform), typeof(Text));
    txtObj.transform.SetParent(btnObj.transform, false);
    var txtRt = txtObj.GetComponent<RectTransform>();
    txtRt.anchorMin = Vector2.zero;
    txtRt.anchorMax = Vector2.one;
    txtRt.sizeDelta = Vector2.zero;

    toggleArrowText = txtObj.GetComponent<Text>();
    toggleArrowText.font = UiTextStyle.BodyFont ?? Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
    toggleArrowText.text = "<";
    toggleArrowText.fontSize = 18;
    toggleArrowText.alignment = TextAnchor.MiddleCenter;
    toggleArrowText.color = new Color(0.96f, 0.78f, 0.26f, 1f);

    toggleButton = btnObj.GetComponent<Button>();
    toggleButton.onClick.AddListener(ToggleQuestBar);
}

{
    IsCollapsed = !IsCollapsed;
    if (slideCoroutine != null) StopCoroutine(slideCoroutine);
    slideCoroutine = StartCoroutine(SlideTo(IsCollapsed ? collapsedPos : expandedPos));

    if (toggleArrowText != null)
    {
        toggleArrowText.text = IsCollapsed ? ">" : "<";
    }
    if (AudioManager.Instance != null) AudioManager.Instance.PlayClickSFX();
}

{
    if (rectTransform == null) yield break;
    Vector2 start = rectTransform.anchoredPosition;
    float elapsed = 0f;
    while (elapsed < DURATION)
    {
        elapsed += Time.unscaledDeltaTime;
        float t = Mathf.SmoothStep(0f, 1f, elapsed / DURATION);
        rectTransform.anchoredPosition = Vector2.Lerp(start, targetPos, t);
        yield return null;
    }
    rectTransform.anchoredPosition = targetPos;
    slideCoroutine = null;
}

