public static CombatNotificationUI Instance
{
    get
    {
        if (_instance == null)
        {
            _instance = FindFirstObjectByType<CombatNotificationUI>(FindObjectsInactive.Include);
        }
        return _instance;
    }
}

methods.body:
{
    if (_instance != null && _instance != this)
    {
        if (Application.isPlaying)
        {
            Destroy(gameObject);
            return;
        }
    }
    _instance = this;
}

    {
        if (containerRect == null) containerRect = GetComponent<RectTransform>();
        if (canvasGroup == null) canvasGroup = GetComponent<CanvasGroup>();

        if (containerRect != null)
        {
            userConfiguredPosition = containerRect.anchoredPosition;
            userConfiguredScale = containerRect.localScale;
        }

        if (Application.isPlaying)
        {
            // Khi nhấn Play: Ẩn banner đi, chờ đến khi có sự kiện Đột phá hoặc Tử trận mới hiện lên
            if (canvasGroup != null)
            {
                canvasGroup.alpha = 0f;
                canvasGroup.blocksRaycasts = false;
                canvasGroup.interactable = false;
            }
        }
        else
        {
            // Trong chế độ Edit (Scene View): Luôn hiện rõ ràng với Alpha = 1 để User dễ quan sát & căn chỉnh
            if (canvasGroup != null)
            {
                canvasGroup.alpha = 1f;
            }
        }
    }

    {
        if (string.IsNullOrEmpty(realmName)) return;

        if (Instance == null)
        {
            Debug.LogWarning("[CombatNotificationUI] Không tìm thấy Banner trong Scene!");
            return;
        }
        Instance.DisplayBreakthrough(realmName);
    }

{
    if (Instance == null)
    {
        Debug.LogWarning("[CombatNotificationUI] Không tìm thấy Banner trong Scene!");
        return;
    }
    Instance.DisplayDeath();
}

    {
        if (titleText != null)
        {
            titleText.text = "ĐỘT PHÁ THÀNH CÔNG";
            titleText.color = new Color(1f, 0.92f, 0.25f); // Vàng kim hào quang
        }

        if (subtitleText != null)
        {
            subtitleText.text = $"[ {realmName} ]";
            subtitleText.color = new Color(0.4f, 1f, 0.7f); // Ngọc bích tinh thuần
        }

        if (extraDetailText != null)
        {
            extraDetailText.text = "Khí tức ngập tràn • Thọ nguyên gia tăng • Sinh lực hồi phục";
            extraDetailText.color = new Color(0.9f, 0.95f, 0.8f, 0.95f);
        }

        // Đổi màu viền và nền sang tông hoàng kim
        Color goldBorder = new Color(1f, 0.84f, 0f, 0.95f);
        if (borderTop != null) borderTop.color = goldBorder;
        if (borderBottom != null) borderBottom.color = goldBorder;
        if (backgroundImage != null) backgroundImage.color = new Color(0.05f, 0.1f, 0.15f, 0.92f);

        // Hiệu ứng Rung màn hình nhẹ chúc mừng
        if (CameraShake.Instance != null && Application.isPlaying)
        {
            CameraShake.Instance.TriggerShake(0.5f, 0.35f);
        }

        isDisplayingTribulationResult = true;

        PlayBannerAnimation(duration: 4.0f);
    }

    {
        if (titleText != null)
        {
            titleText.text = "ĐẠO THÂN TỬ TRẬN";
            titleText.color = new Color(1f, 0.25f, 0.25f); // Đỏ thẫm máu lửa
        }

        if (subtitleText != null)
        {
            subtitleText.text = "Bất Hạnh Vẫn Lạc — Đạo Tâm Bất Diệt";
            subtitleText.color = new Color(1f, 0.75f, 0.75f);
        }

        if (extraDetailText != null)
        {
            extraDetailText.text = "Làm mới tiến trình ải • Đang trùng tu hồi sinh...";
            extraDetailText.color = new Color(0.85f, 0.85f, 0.85f, 0.9f);
        }

        // Đổi màu viền và nền sang tông đỏ đậm máu
        Color bloodBorder = new Color(0.9f, 0.15f, 0.15f, 0.95f);
        if (borderTop != null) borderTop.color = bloodBorder;
        if (borderBottom != null) borderBottom.color = bloodBorder;
        if (backgroundImage != null) backgroundImage.color = new Color(0.15f, 0.03f, 0.03f, 0.94f);

        // Rung nhẹ khi ngã xuống
        if (CameraShake.Instance != null && Application.isPlaying)
        {
            CameraShake.Instance.TriggerShake(0.4f, 0.3f);
        }

        isDisplayingTribulationResult = false;

        PlayBannerAnimation(duration: 2.2f);
    }

{
    if (Instance == null) return;
    Instance.DisplayTribulationFailed(lostTuVi);
}

    {
        if (titleText != null)
        {
            titleText.text = "ĐỘ KIẾP THẤT BẠI";
            titleText.color = new Color(1f, 0.3f, 0.2f); // Đỏ sấm sét
        }

        if (subtitleText != null)
        {
            subtitleText.text = $"[ Bị Thiên Kiếp Phản Phệ • Tổn Thất {CultivationManager.TribulationFailureLossRate:0%} Tu Vi (-{lostTuVi:F0}) ]";
            subtitleText.color = new Color(1f, 0.85f, 0.4f); // Vàng cam cảnh báo
        }

        if (extraDetailText != null)
        {
            extraDetailText.text = "Đạo thân thọ thương • Hãy củng cố tu vi và nâng cấp phi kiếm trước khi thử lại!";
            extraDetailText.color = new Color(0.95f, 0.85f, 0.85f, 0.95f);
        }

        Color thunderBorder = new Color(1f, 0.4f, 0.1f, 0.95f);
        if (borderTop != null) borderTop.color = thunderBorder;
        if (borderBottom != null) borderBottom.color = thunderBorder;
        if (backgroundImage != null) backgroundImage.color = new Color(0.18f, 0.05f, 0.05f, 0.95f);

        if (CameraShake.Instance != null && Application.isPlaying)
        {
            CameraShake.Instance.TriggerShake(0.6f, 0.4f);
        }

        isDisplayingTribulationResult = true;

        PlayBannerAnimation(duration: 4.2f);
    }

    {
        if (!Application.isPlaying)
        {
            if (canvasGroup != null) canvasGroup.alpha = 1f;
            return;
        }

        if (activeAnimRoutine != null)
        {
            StopCoroutine(activeAnimRoutine);
        }
        activeAnimRoutine = StartCoroutine(AnimateBannerCoroutine(duration));
    }

    {
        gameObject.SetActive(true);
        transform.SetAsLastSibling();

        if (containerRect == null) containerRect = GetComponent<RectTransform>();
        if (canvasGroup == null) canvasGroup = GetComponent<CanvasGroup>();

        // Giữ vị trí mà người dùng đã căn chỉnh trên Editor
        Vector2 basePosition = userConfiguredPosition;
        if (basePosition == Vector2.zero && containerRect != null)
        {
            basePosition = containerRect.anchoredPosition;
        }
        Vector3 baseScale = userConfiguredScale;

        // Giai đoạn 1: Pop In (Scale từ 0.6 nảy lên 1.12 rồi về 1.0, Alpha từ 0 lên 1) trong 0.25 giây
        float popTime = 0.25f;
        float elapsed = 0f;
        while (elapsed < popTime)
        {
            elapsed += Time.unscaledDeltaTime;
            float t = Mathf.Clamp01(elapsed / popTime);

            float scaleProgress;
            if (t < 0.7f)
            {
                scaleProgress = Mathf.Lerp(0.6f, 1.12f, t / 0.7f);
            }
            else
            {
                scaleProgress = Mathf.Lerp(1.12f, 1.0f, (t - 0.7f) / 0.3f);
            }

            if (containerRect != null)
            {
                containerRect.localScale = baseScale * scaleProgress;
                containerRect.anchoredPosition = basePosition;
            }
            if (canvasGroup != null)
            {
                canvasGroup.alpha = Mathf.Lerp(0f, 1f, t * 1.5f);
            }
            yield return null;
        }

        if (containerRect != null) containerRect.localScale = baseScale;
        if (canvasGroup != null) canvasGroup.alpha = 1f;

        // Giai đoạn 2: Giữ cố định và trôi nhẹ lên trên 15px
        float holdTime = Mathf.Max(0.5f, duration - 0.7f);
        elapsed = 0f;
        while (elapsed < holdTime)
        {
            elapsed += Time.unscaledDeltaTime;
            float floatT = elapsed / holdTime;
            if (containerRect != null)
            {
                containerRect.anchoredPosition = basePosition + new Vector2(0, floatT * 15f);
            }
            yield return null;
        }

        // Giai đoạn 3: Fade Out mượt mà trong 0.45 giây
        float fadeTime = 0.45f;
        elapsed = 0f;
        Vector2 startFadePos = containerRect != null ? containerRect.anchoredPosition : basePosition;
        while (elapsed < fadeTime)
        {
            elapsed += Time.unscaledDeltaTime;
            float t = Mathf.Clamp01(elapsed / fadeTime);
            if (canvasGroup != null)
            {
                canvasGroup.alpha = Mathf.Lerp(1f, 0f, t);
            }
            if (containerRect != null)
            {
                containerRect.anchoredPosition = startFadePos + new Vector2(0, t * 10f);
            }
            yield return null;
        }

        if (canvasGroup != null) canvasGroup.alpha = 0f;
        if (containerRect != null)
        {
            containerRect.anchoredPosition = basePosition;
            containerRect.localScale = baseScale;
        }
        isDisplayingTribulationResult = false;

        activeAnimRoutine = null;

    }

    {

        if (!force && isDisplayingTribulationResult)

        {

            return;

        }



        if (activeAnimRoutine != null)

        {

            StopCoroutine(activeAnimRoutine);

            activeAnimRoutine = null;

        }

        isDisplayingTribulationResult = false;

        if (canvasGroup != null) canvasGroup.alpha = 0f;
        if (containerRect != null && userConfiguredPosition != Vector2.zero)
        {
            containerRect.anchoredPosition = userConfiguredPosition;
            containerRect.localScale = userConfiguredScale;
        }
    }

{
    DisplayBreakthrough("Luyện Khí Tầng 6");
}

{
    DisplayDeath();
}

{
    if (title == null || title.transform.parent == null) return null;
    var parent = title.transform.parent as RectTransform;
    if (parent == null) return null;
    var bar = parent.GetComponent<CultivationPhaseBarUI>();
    if (bar == null) bar = parent.gameObject.AddComponent<CultivationPhaseBarUI>();
    bar.Build(title);
    return bar;
}

{
    stageLabel = title;
    var titleRect = (RectTransform)title.transform;
    titleRect.anchorMin = new Vector2(0.012f, 0f);
    titleRect.anchorMax = new Vector2(0.38f, 1f);
    titleRect.offsetMin = titleRect.offsetMax = Vector2.zero;
    title.alignment = TextAnchor.MiddleLeft;
    title.fontSize = GetComponentInParent<JadeUITheme>() != null ? 28 : 21;
    title.raycastTarget = false;

    tribulationButton = GetComponent<Button>() ?? gameObject.AddComponent<Button>();
    tribulationButton.targetGraphic = GetComponent<Graphic>() ?? title;
    tribulationButton.transition = Selectable.Transition.None;
    tribulationButton.navigation = new Navigation { mode = Navigation.Mode.None };
    tribulationButton.onClick.RemoveListener(TribulationModalUI.Open);
    tribulationButton.onClick.AddListener(TribulationModalUI.Open);

    var root = transform.Find("PhaseSegments") as RectTransform;
    if (root == null)
    {
        var go = new GameObject("PhaseSegments", typeof(RectTransform));
        root = (RectTransform)go.transform;
        root.SetParent(transform, false);
    }
    root.anchorMin = new Vector2(0.39f, 0.15f);
    root.anchorMax = new Vector2(0.99f, 0.85f);
    root.offsetMin = root.offsetMax = Vector2.zero;

    if (fills == null || fills.Length != 4) fills = new UnityEngine.UI.Image[4];
    if (labels == null || labels.Length != 4) labels = new UnityEngine.UI.Text[4];
    for (int i = 0; i < PhaseLabels.Length; i++)
    {
        var segment = root.Find("Phase_" + i) as RectTransform;
        if (segment == null)
        {
            var go = new GameObject("Phase_" + i, typeof(RectTransform), typeof(UnityEngine.UI.Image));
            segment = (RectTransform)go.transform;
            segment.SetParent(root, false);
        }
        segment.anchorMin = new Vector2(i * 0.25f, 0f);
        segment.anchorMax = new Vector2((i + 1) * 0.25f, 1f);
        segment.offsetMin = new Vector2(2f, 0f);
        segment.offsetMax = new Vector2(-2f, 0f);
        var background = segment.GetComponent<UnityEngine.UI.Image>();
        background.color = new Color(0.08f, 0.14f, 0.19f, 0.96f);
        background.raycastTarget = false;

        var fill = segment.Find("Fill") as RectTransform;
        if (fill == null)
        {
            var go = new GameObject("Fill", typeof(RectTransform), typeof(UnityEngine.UI.Image));
            fill = (RectTransform)go.transform;
            fill.SetParent(segment, false);
        }
        fill.anchorMin = Vector2.zero;
        fill.anchorMax = Vector2.one;
        fill.offsetMin = fill.offsetMax = Vector2.zero;
        fills[i] = fill.GetComponent<UnityEngine.UI.Image>();
        fills[i].type = UnityEngine.UI.Image.Type.Simple;
        fills[i].raycastTarget = false;

        var label = segment.Find("Label") as RectTransform;
        if (label == null)
        {
            var go = new GameObject("Label", typeof(RectTransform), typeof(UnityEngine.UI.Text));
            label = (RectTransform)go.transform;
            label.SetParent(segment, false);
        }
        label.anchorMin = Vector2.zero;
        label.anchorMax = Vector2.one;
        label.offsetMin = label.offsetMax = Vector2.zero;
        labels[i] = label.GetComponent<UnityEngine.UI.Text>();
        labels[i].font = title.font;
        labels[i].fontSize = GetComponentInParent<JadeUITheme>() != null ? 26 : 19;
        labels[i].alignment = TextAnchor.MiddleCenter;
        labels[i].text = PhaseLabels[i];
        labels[i].raycastTarget = false;
    }
}

{
    tribulationButton.interactable = tribulationReady;
    tribulationButton.targetGraphic.raycastTarget = tribulationReady;
    if (fills == null || labels == null || fills.Length != 4 || labels.Length != 4) return;
    SaveMigration.MapLegacyStage(stageIndex, out _, out int subLevel);
    int currentPhase = CultivationDisplay.PhaseIndex(subLevel);
    float phaseProgress = CultivationDisplay.PhaseProgress(stageIndex, stageFraction);
    for (int i = 0; i < 4; i++)
    {
        if (fills[i] == null || labels[i] == null) continue;
        float progress = i < currentPhase ? 1f : i == currentPhase ? phaseProgress : 0f;
        var fillRect = (RectTransform)fills[i].transform;
        fillRect.anchorMax = new Vector2(progress, 1f);
        fillRect.offsetMin = fillRect.offsetMax = Vector2.zero;
        fills[i].color = i == 3 ? new Color(0.98f, 0.76f, 0.22f, 0.95f) :
            new Color(0.20f, 0.72f, 0.66f, 0.95f);
        labels[i].color = i == currentPhase ? Color.white :
            i < currentPhase ? new Color(0.82f, 0.96f, 0.88f) : new Color(0.52f, 0.60f, 0.65f);
        labels[i].text = i == 3 && tribulationReady ? "MỞ ĐỘ KIẾP" : PhaseLabels[i];
    }
}

