    if (detailsHeader != null && detailsHeader.Find("BtnDaoAn") == null)
    {
        var entry = CreateButton("BtnDaoAn", detailsHeader, "Đạo Ấn",
            new Vector2(0f, 0f), new Vector2(0f, 1f), new Vector2(8f, 5f), new Vector2(110f, -5f),
