    btnDblRt.sizeDelta = new Vector2(240, 60);

    GameObject btnDblTxtObj = new GameObject("Text", typeof(RectTransform), typeof(Text));
    btnDblTxtObj.transform.SetParent(btnDoubleObj.transform, false);
