    bctRt.offsetMin = Vector2.zero; bctRt.offsetMax = Vector2.zero;

    // Setup component references
    OfflineRewardPopupUI popup = modalObj.GetComponent<OfflineRewardPopupUI>();
    popup.canvasGroup = cg;
