    bDbl.onClick.RemoveAllListeners();
    bDbl.onClick.AddListener(popup.OnClaimDoubleClicked);
    bClose.onClick.RemoveAllListeners();
    bClose.onClick.AddListener(popup.OnCloseClicked);

    popup.isOpen = false;
    _instance = popup;
