    var statsBar = new GameObject("StatsBar", typeof(RectTransform), typeof(Image));
    statsBar.transform.SetParent(box.transform, false);
    var srt = statsBar.GetComponent<RectTransform>();
    srt.anchorMin = new Vector2(0f, 1f);
    srt.anchorMax = new Vector2(1f, 1f);
    srt.offsetMin = new Vector2(16f, -132f);
    srt.offsetMax = new Vector2(-16f, -74f);
    statsBar.GetComponent<Image>().color = new Color(0.04f, 0.06f, 0.12f, 0.96f);

    walletText = CreateText(statsBar.transform, "Wallet", "✨ Cơ Duyên: 0 CD", 15, FontStyle.Bold, Vector2.zero, new Color(1f, 0.85f, 0.3f));
    var wrt = walletText.GetComponent<RectTransform>();
    wrt.anchorMin = new Vector2(0f, 0f);
    wrt.anchorMax = new Vector2(0.5f, 1f);
    wrt.offsetMin = new Vector2(14f, 0f);
    wrt.offsetMax = new Vector2(-10f, 0f);
    walletText.alignment = TextAnchor.MiddleLeft;

    freeAttemptsText = CreateText(statsBar.transform, "FreeAttempts", "Lượt Miễn Phí: 1/1", 15, FontStyle.Bold, Vector2.zero, new Color(0.3f, 1f, 0.5f));
    var frt = freeAttemptsText.GetComponent<RectTransform>();
    frt.anchorMin = new Vector2(0.5f, 0f);
    frt.anchorMax = new Vector2(1f, 1f);
    frt.offsetMin = new Vector2(10f, 0f);
    frt.offsetMax = new Vector2(-14f, 0f);
    freeAttemptsText.alignment = TextAnchor.MiddleRight;

    // 7. ScrollView danh sách 5 Bí Cảnh
    var scrollGo = new GameObject("ScrollView", typeof(RectTransform), typeof(ScrollRect), typeof(Image));
    scrollGo.transform.SetParent(box.transform, false);
    var scrt = scrollGo.GetComponent<RectTransform>();
    scrt.anchorMin = Vector2.zero;
    scrt.anchorMax = Vector2.one;
    scrt.offsetMin = new Vector2(16f, 76f);
    scrt.offsetMax = new Vector2(-16f, -140f);
    scrollGo.GetComponent<Image>().color = Color.clear;

    var viewport = new GameObject("Viewport", typeof(RectTransform), typeof(RectMask2D));
    viewport.transform.SetParent(scrollGo.transform, false);
    var vprt = viewport.GetComponent<RectTransform>();
    vprt.anchorMin = Vector2.zero;
    vprt.anchorMax = Vector2.one;
    vprt.offsetMin = vprt.offsetMax = Vector2.zero;

    var content = new GameObject("Content", typeof(RectTransform), typeof(VerticalLayoutGroup), typeof(ContentSizeFitter));
    content.transform.SetParent(viewport.transform, false);
    var crt = content.GetComponent<RectTransform>();
    crt.anchorMin = new Vector2(0f, 1f);
    crt.anchorMax = new Vector2(1f, 1f);
    crt.pivot = new Vector2(0.5f, 1f);
    crt.offsetMin = crt.offsetMax = Vector2.zero;

    var vlg = content.GetComponent<VerticalLayoutGroup>();
    vlg.childControlWidth = true;
    vlg.childControlHeight = false;
    vlg.childForceExpandWidth = true;
    vlg.childForceExpandHeight = false;
    vlg.spacing = 10f;
    vlg.padding = new RectOffset(4, 4, 6, 6);

    var csf = content.GetComponent<ContentSizeFitter>();
    csf.verticalFit = ContentSizeFitter.FitMode.PreferredSize;

    var scrollRect = scrollGo.GetComponent<ScrollRect>();
    scrollRect.content = crt;
    scrollRect.viewport = vprt;
    scrollRect.horizontal = false;
    scrollRect.vertical = true;
    scrollRect.movementType = ScrollRect.MovementType.Clamped;

    // Sinh 5 thẻ Bí Cảnh
    CreateRealmCards(content.transform);

    // 8. Nút Đóng Dưới Cùng
    var closeBottom = new GameObject("CloseButton", typeof(RectTransform), typeof(Image), typeof(Button), typeof(Outline));
    closeBottom.transform.SetParent(box.transform, false);
    var cbrt = closeBottom.GetComponent<RectTransform>();
    cbrt.anchorMin = new Vector2(0.2f, 0f);
    cbrt.anchorMax = new Vector2(0.8f, 0f);
    cbrt.offsetMin = new Vector2(0f, 14f);
    cbrt.offsetMax = new Vector2(0f, 66f);
    closeBottom.GetComponent<Image>().color = new Color(0.18f, 0.22f, 0.32f, 0.95f);
    var cbol = closeBottom.GetComponent<Outline>();
    cbol.effectColor = new Color(0.85f, 0.45f, 1f, 0.7f);
    cbol.effectDistance = new Vector2(1f, -1f);

    var cbtxt = CreateText(closeBottom.transform, "Text", "ĐÓNG GIAO DIỆN", 15, FontStyle.Bold, Vector2.zero, Color.white);
    cbtxt.alignment = TextAnchor.MiddleCenter;
    closeBottom.GetComponent<Button>().onClick.AddListener(Close);

    modalOverlay.SetActive(false);
}

{
    var card = new GameObject("Card_" + type, typeof(RectTransform), typeof(Image), typeof(Outline), typeof(LayoutElement));
    card.transform.SetParent(parent, false);
    var crt = card.GetComponent<RectTransform>();
    crt.sizeDelta = new Vector2(0f, 130f);
    var le = card.GetComponent<LayoutElement>();
    le.minHeight = 130f;
    le.preferredHeight = 130f;
    card.GetComponent<Image>().color = bgColor;
    var ol = card.GetComponent<Outline>();
    ol.effectColor = new Color(accentColor.r, accentColor.g, accentColor.b, 0.5f);
    ol.effectDistance = new Vector2(1f, -1f);

    // Title
    var tTxt = CreateText(card.transform, "Title", title, 15, FontStyle.Bold, Vector2.zero, accentColor);
    var trt = tTxt.GetComponent<RectTransform>();
    trt.anchorMin = new Vector2(0f, 1f);
    trt.anchorMax = new Vector2(1f, 1f);
    trt.offsetMin = new Vector2(14f, -32f);
    trt.offsetMax = new Vector2(-130f, -4f);
    tTxt.alignment = TextAnchor.MiddleLeft;

    // Desc
    var dTxt = CreateText(card.transform, "Desc", desc, 12, FontStyle.Normal, Vector2.zero, new Color(0.85f, 0.85f, 0.9f));
    var drt = dTxt.GetComponent<RectTransform>();
    drt.anchorMin = new Vector2(0f, 1f);
    drt.anchorMax = new Vector2(1f, 1f);
    drt.offsetMin = new Vector2(14f, -76f);
    drt.offsetMax = new Vector2(-130f, -34f);
    dTxt.alignment = TextAnchor.UpperLeft;

    // Reward Tag
    var rTxt = CreateText(card.transform, "Reward", reward, 11, FontStyle.Italic, Vector2.zero, new Color(1f, 0.85f, 0.35f));
    var rrt = rTxt.GetComponent<RectTransform>();
    rrt.anchorMin = new Vector2(0f, 0f);
    rrt.anchorMax = new Vector2(1f, 0f);
    rrt.offsetMin = new Vector2(14f, 6f);
    rrt.offsetMax = new Vector2(-130f, 44f);
    rTxt.alignment = TextAnchor.MiddleLeft;

    // Button Enter
    var btnGo = new GameObject("BtnEnter", typeof(RectTransform), typeof(Image), typeof(Button), typeof(Outline));
    btnGo.transform.SetParent(card.transform, false);
    var brt = btnGo.GetComponent<RectTransform>();
    brt.anchorMin = new Vector2(1f, 0.5f);
    brt.anchorMax = new Vector2(1f, 0.5f);
    brt.anchoredPosition = new Vector2(-68f, 0f);
    brt.sizeDelta = new Vector2(116f, 50f);
    btnGo.GetComponent<Image>().color = new Color(0.18f, 0.45f, 0.25f, 0.95f);
    var bol = btnGo.GetComponent<Outline>();
    bol.effectColor = new Color(0.4f, 1f, 0.6f, 0.8f);
    bol.effectDistance = new Vector2(1f, -1f);

    var btxt = CreateText(btnGo.transform, "Text", "VÀO ẢI", 13, FontStyle.Bold, Vector2.zero, Color.white);
    btxt.alignment = TextAnchor.MiddleCenter;

    var btn = btnGo.GetComponent<Button>();
    btn.onClick.AddListener(() =>
    {
        OnEnterRealmClicked(type);
    });
    enterButtons.Add(btn);
}

{
    if (SecretRealmService.Instance == null) return;

    if (!SecretRealmService.Instance.CanEnter())
    {
        if (GameLogger.Instance != null)
            GameLogger.Instance.Log("❌ Đã hết lượt miễn phí! Cần 5 Cơ Duyên (CD) để mở cổng.", Color.yellow);
        return;
    }

    if (SecretRealmService.Instance.TryConsumeEntry(out bool usedFree))
    {
        Close();
        if (SecretRealmPlayController.Instance == null)
        {
            var pcGo = GameObject.Find("Canvas");
            if (pcGo != null && pcGo.GetComponent<SecretRealmPlayController>() == null)
                pcGo.AddComponent<SecretRealmPlayController>();
        }
        SecretRealmPlayController.Instance?.LaunchMiniGame(type);
    }
}

{
    if (SecretRealmService.Instance == null) return;

    bool hasFree = SecretRealmService.Instance.HasFreeAttempt();
    int cd = EconomyManager.Instance != null ? EconomyManager.Instance.currentCoDuyen : 0;

    if (walletText != null)
    {
        walletText.text = $"✨ Ví Cơ Duyên: <color=#FFE666>{cd} CD</color>";
    }

    if (freeAttemptsText != null)
    {
        if (hasFree)
        {
            freeAttemptsText.text = "Lượt Miễn Phí: <color=#55FF88>1 / 1</color>";
        }
        else
        {
            freeAttemptsText.text = "Phí Vào Cổng: <color=#FFB84D>5 CD / Lần</color>";
        }
    }

    // Cập nhật text trên các nút vào ải
    foreach (var b in enterButtons)
    {
        if (b == null) continue;
        var t = b.GetComponentInChildren<Text>();
        if (t == null) continue;

        if (hasFree)
        {
            t.text = "<b>MIỄN PHÍ\n(1/1)</b>";
            b.GetComponent<Image>().color = new Color(0.15f, 0.45f, 0.25f, 0.95f);
            b.interactable = true;
        }
        else if (cd >= SecretRealmService.CO_DUYEN_ENTRY_COST)
        {
            t.text = "<b>VÀO ẢI\n(5 CD)</b>";
            b.GetComponent<Image>().color = new Color(0.45f, 0.3f, 0.12f, 0.95f);
            b.interactable = true;
        }
        else
        {
            t.text = "<b>CẦN 5 CD</b>";
            b.GetComponent<Image>().color = new Color(0.2f, 0.2f, 0.25f, 0.7f);
            b.interactable = false;
        }
    }
}

{
    if (modalOverlay == null) return;
    walletText = modalOverlay.transform.Find("ModalBox/StatsBar/Wallet")?.GetComponent<Text>();
    freeAttemptsText = modalOverlay.transform.Find("ModalBox/StatsBar/FreeAttempts")?.GetComponent<Text>();

    var btnX = modalOverlay.transform.Find("ModalBox/BtnCloseX")?.GetComponent<Button>();
    if (btnX != null)
    {
        btnX.onClick.RemoveAllListeners();
        btnX.onClick.AddListener(Close);
    }

    var btnBackdrop = modalOverlay.GetComponent<Button>();
    if (btnBackdrop != null)
    {
        btnBackdrop.onClick.RemoveAllListeners();
        btnBackdrop.onClick.AddListener(Close);
    }

    var btnCloseBottom = modalOverlay.transform.Find("ModalBox/CloseButton")?.GetComponent<Button>();
    if (btnCloseBottom != null)
    {
        btnCloseBottom.onClick.RemoveAllListeners();
        btnCloseBottom.onClick.AddListener(Close);
    }

    enterButtons.Clear();
    var content = modalOverlay.transform.Find("ModalBox/ScrollView/Viewport/Content");
    if (content != null)
    {
        SecretRealmType[] types = {
            SecretRealmType.HordeSurvival,
            SecretRealmType.BarrierBreak,
            SecretRealmType.DanCauldron,
            SecretRealmType.LightningDodge,
            SecretRealmType.SwordTomb
        };

        for (int i = 0; i < types.Length; i++)
        {
            var type = types[i];
            var card = content.Find("Card_" + type);
            if (card != null)
            {
                var btnEnter = card.Find("BtnEnter")?.GetComponent<Button>();
                if (btnEnter != null)
                {
                    btnEnter.onClick.RemoveAllListeners();
                    btnEnter.onClick.AddListener(() => OnEnterRealmClicked(type));
                    enterButtons.Add(btnEnter);
                }
            }
        }
    }
}

{
    var go = new GameObject(name, typeof(RectTransform), typeof(Text));
    go.transform.SetParent(parent, false);
    var rt = go.GetComponent<RectTransform>();
    rt.anchoredPosition = pos;
    rt.sizeDelta = new Vector2(300f, 30f);
    var txt = go.GetComponent<Text>();
    txt.font = DefaultFont;
    txt.fontSize = size;
    txt.fontStyle = style;
    txt.color = col;
    txt.text = val;
    return txt;
}

properties.source:
public static Font DefaultFont
{
    get
    {
        var f = UiTextStyle.BodyFont;
        if (f != null) return f;
        f = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        if (f != null) return f;
        return Resources.GetBuiltinResource<Font>("Arial.ttf");
    }
}

methods.body:
{
    if (Instance != null && Instance != this) { Destroy(this); return; }
    Instance = this;
    LoadResourceSprites();
}

{
    spBgHorde = Resources.Load<Sprite>("SecretRealm/bicanh_horde_survival");
    spBgBarrier = Resources.Load<Sprite>("SecretRealm/bicanh_barrier_break");
    spBgCauldron = Resources.Load<Sprite>("SecretRealm/bicanh_dan_cauldron");
    spSwordAtlas = Resources.LoadAll<Sprite>("SecretRealm/kiem");
    spHitSpark = Resources.Load<Sprite>("SecretRealm/Tex_VFX_HitSpark");
    spRuneTelegraph = Resources.Load<Sprite>("SecretRealm/Tex_VFX_RuneTelegraph");
    spSoftGlow = Resources.Load<Sprite>("SecretRealm/Tex_VFX_SoftGlow");
    spTaiji = Resources.Load<Sprite>("SecretRealm/Tex_VFX_Taiji");
    spVanKiem = Resources.Load<Sprite>("SecretRealm/VanKiemQuyTong");
    spSamSet = Resources.Load<Sprite>("SecretRealm/SamSet");
    spChuongAn = Resources.Load<Sprite>("SecretRealm/ChuongAn");
    spPhapTran = Resources.Load<Sprite>("SecretRealm/PhapTran");
}

{
    LoadResourceSprites();
    activeType = type;
    currentScore = 0;
    isGameRunning = true;

    EnsurePlayUI();
    rootModal.SetActive(true);
    rootModal.transform.SetAsLastSibling();
    if (resultModal != null) resultModal.SetActive(false);

    ClearDynamicArena();

    switch (type)
    {
        case SecretRealmType.HordeSurvival:
            SetupHordeSurvival();
            break;
        case SecretRealmType.BarrierBreak:
            SetupBarrierBreak();
            break;
        case SecretRealmType.DanCauldron:
            SetupDanCauldron();
            break;
        case SecretRealmType.LightningDodge:
            SetupLightningDodge();
            break;
        case SecretRealmType.SwordTomb:
            SetupSwordTomb();
            break;
    }
}

{
    if (!isGameRunning) return;

    if (activeType != SecretRealmType.DanCauldron && activeType != SecretRealmType.SwordTomb)
    {
        timeRemaining -= Time.deltaTime;
        if (timerText != null)
        {
            timerText.text = $"⏱️ <color=#FFE666>{Mathf.Max(0f, timeRemaining):0.0}s</color>";
        }
    }

    switch (activeType)
    {
        case SecretRealmType.HordeSurvival:
            UpdateHordeSurvival();
            break;
        case SecretRealmType.BarrierBreak:
            UpdateBarrierBreak();
            break;
        case SecretRealmType.DanCauldron:
            // Tự động kết thúc khi người chơi bấm chọn
            break;
        case SecretRealmType.LightningDodge:
            UpdateLightningDodge();
            break;
        case SecretRealmType.SwordTomb:
            UpdateSwordTomb();
            break;
    }

    if (timeRemaining <= 0f && activeType != SecretRealmType.DanCauldron && activeType != SecretRealmType.SwordTomb)
    {
        EndMiniGame();
    }
}

{
    timeRemaining = 30f;
    hordeKilled = 0;
    nextHordeSpawnTime = 0f;
    ClearGameObjects(activeDemonGoList);

    SetHeader(
        "👹 VẠN MA TRIỀU DÂNG (SINH TỒN 30S)",
        new Color(0.95f, 0.25f, 0.3f),
        "🎯 MỤC TIÊU: Trảm diệt 50 Yêu Ma trước khi cạn kiệt thời gian!",
        "👉 CÁCH CHƠI: Chạm trực tiếp vào Yêu Ma hoặc bấm nút [Vạn Kiếm Quy Tông] bên dưới để quét sạch!"
    );

    if (arenaBgImage != null && spBgHorde != null)
    {
        arenaBgImage.sprite = spBgHorde;
        arenaBgImage.color = new Color(0.9f, 0.85f, 0.85f, 0.95f);
    }

    scoreTitleText.text = "⚔️ YÊU MA ĐÃ TRẢM:";
    UpdateHordeScoreUI();

    CreateBottomActionButton("⚔️ VẠN KIẾM QUY TÔNG (QUÉT SẠCH 5 QUÁI)", spVanKiem, new Color(0.75f, 0.15f, 0.25f), () =>
    {
        TriggerHordeSuperSlash();
    });

    for (int i = 0; i < 6; i++) SpawnHordeDemon();
}

{
    if (Time.time >= nextHordeSpawnTime && activeDemonGoList.Count < 12 && (hordeKilled + activeDemonGoList.Count) < HORDE_TARGET)
    {
        nextHordeSpawnTime = Time.time + 0.45f;
        SpawnHordeDemon();
    }

    if (activeDemonGoList.Count > 0 && UnityEngine.Random.value < 0.12f)
    {
        KillOneHordeDemon(true);
    }
}

{
    if (arenaContainer == null) return;

    var go = new GameObject("DemonBadge_" + activeDemonGoList.Count, typeof(RectTransform), typeof(Image), typeof(Button), typeof(Outline));
    go.transform.SetParent(arenaContainer, false);
    var rt = go.GetComponent<RectTransform>();
    rt.sizeDelta = new Vector2(64f, 64f);

    float rx = UnityEngine.Random.Range(-155f, 155f);
    float ry = UnityEngine.Random.Range(-175f, 155f);
    rt.anchoredPosition = new Vector2(rx, ry);

    var img = go.GetComponent<Image>();
    img.sprite = spSoftGlow;
    img.color = new Color(0.95f, 0.15f, 0.2f, 0.95f);

    var ol = go.GetComponent<Outline>();
    ol.effectColor = new Color(1f, 0.9f, 0.3f, 0.95f);
    ol.effectDistance = new Vector2(2f, -2f);

    // Biểu tượng mặt quỷ ở giữa
    var iconGo = new GameObject("Icon", typeof(RectTransform), typeof(Text));
    iconGo.transform.SetParent(go.transform, false);
    var irt = iconGo.GetComponent<RectTransform>();
    irt.anchorMin = Vector2.zero;
    irt.anchorMax = Vector2.one;
    irt.offsetMin = irt.offsetMax = Vector2.zero;
    var itxt = iconGo.GetComponent<Text>();
    itxt.font = DefaultFont;
    itxt.fontSize = 28;
    itxt.alignment = TextAnchor.MiddleCenter;
    itxt.color = Color.white;
    string[] demonIcons = { "👹", "👺", "💀", "👿" };
    itxt.text = demonIcons[UnityEngine.Random.Range(0, demonIcons.Length)];

    // Tên quái
    var nameGo = new GameObject("Name", typeof(RectTransform), typeof(Text));
    nameGo.transform.SetParent(go.transform, false);
    var nrt = nameGo.GetComponent<RectTransform>();
    nrt.anchoredPosition = new Vector2(0f, -40f);
    nrt.sizeDelta = new Vector2(76f, 18f);
    var ntxt = nameGo.GetComponent<Text>();
    ntxt.font = DefaultFont;
    ntxt.fontSize = 11;
    ntxt.fontStyle = FontStyle.Bold;
    ntxt.alignment = TextAnchor.MiddleCenter;
    ntxt.color = new Color(1f, 0.85f, 0.7f);
    ntxt.text = "Huyết Ma";

    var btn = go.GetComponent<Button>();
    btn.onClick.AddListener(() =>
    {
        if (activeDemonGoList.Contains(go))
        {
            SpawnFloatingText("-150.000 (Trảm!)", rt.anchoredPosition, new Color(1f, 0.4f, 0.2f), 1.2f);
            SpawnHitSpark(rt.anchoredPosition, Color.yellow, 64f);
            activeDemonGoList.Remove(go);
            Destroy(go);
            hordeKilled++;
            currentScore = hordeKilled;
            UpdateHordeScoreUI();
            ShakeArena(0.12f, 4f);
            if (hordeKilled >= HORDE_TARGET) EndMiniGame();
        }
    });

    activeDemonGoList.Add(go);
}

{
    int kills = Mathf.Min(activeDemonGoList.Count, 5);
    if (kills == 0) return;

    ShakeArena(0.25f, 8f);
    SpawnHitSpark(Vector2.zero, new Color(1f, 0.9f, 0.2f), 160f);

    for (int i = 0; i < kills; i++)
    {
        KillOneHordeDemon(false);
    }
}

{
    if (activeDemonGoList.Count == 0) return;
    var go = activeDemonGoList[0];
    activeDemonGoList.RemoveAt(0);
    if (go != null)
    {
        var rt = go.GetComponent<RectTransform>();
        Vector2 p = rt != null ? rt.anchoredPosition : Vector2.zero;
        string txt = isIdleDps ? "-50.000" : "-999.999 (Vạn Kiếm!)";
        Color col = isIdleDps ? Color.white : new Color(1f, 0.85f, 0.2f);
        SpawnFloatingText(txt, p, col, isIdleDps ? 1f : 1.3f);
        SpawnHitSpark(p, Color.red, 52f);
        Destroy(go);
    }

    hordeKilled++;
    currentScore = hordeKilled;
    UpdateHordeScoreUI();
    if (hordeKilled >= HORDE_TARGET) EndMiniGame();
}

{
    if (scoreValueText != null)
        scoreValueText.text = $"{hordeKilled} / {HORDE_TARGET}";

    float progress = Mathf.Clamp01((float)hordeKilled / HORDE_TARGET);
    if (mainProgressBar != null) mainProgressBar.fillAmount = progress;
    if (progressBarText != null) progressBarText.text = $"TIẾN ĐỘ TRẢM MA: {Mathf.RoundToInt(progress * 100f)}%";
}

{
    timeRemaining = 20f;
    barrierCurrentHp = barrierMaxHp;
    currentScore = 0;

    SetHeader(
        "🗿 TRẢM PHÁ CẤM CHẾ (DPS CHECK 20S)",
        new Color(0.2f, 0.75f, 1f),
        "🎯 MỤC TIÊU: Dồn sát thương phá nát Thạch Bi Thượng Cổ trước khi cấm chế kích hoạt!",
        "👉 CÁCH CHƠI: Chạm liên tục vào nút [Khai Thiên Trảm] bên dưới để xuất kiếm phá tan cấm chế!"
    );

    if (arenaBgImage != null && spBgBarrier != null)
    {
        arenaBgImage.sprite = spBgBarrier;
        arenaBgImage.color = new Color(0.85f, 0.9f, 1f, 0.95f);
    }

    scoreTitleText.text = "🗿 TIẾN ĐỘ PHÁ CẤM:";
    scoreValueText.text = "0%";

    CreateAncientMonolithStele();

    Sprite attackIcon = spChuongAn != null ? spChuongAn : (spSwordAtlas != null && spSwordAtlas.Length > 7 ? spSwordAtlas[7] : null);
    CreateBottomActionButton("⚡ KHAI THIÊN TRẢM! (+50.000 DMG)", attackIcon, new Color(0.15f, 0.45f, 0.85f), () =>
    {
        HitBarrier(50000f, true);
    });

    UpdateBarrierScoreUI();
}

{
    if (arenaContainer == null) return;

    var steleGo = new GameObject("AncientStele", typeof(RectTransform), typeof(Image), typeof(Outline));
    steleGo.transform.SetParent(arenaContainer, false);
    steleTransform = steleGo.GetComponent<RectTransform>();
    steleTransform.anchoredPosition = new Vector2(0f, 20f);
    steleTransform.sizeDelta = new Vector2(240f, 320f);

    var img = steleGo.GetComponent<Image>();
    img.color = new Color(0.14f, 0.17f, 0.25f, 0.98f);

    var ol = steleGo.GetComponent<Outline>();
    ol.effectColor = new Color(0.3f, 0.8f, 1f, 0.9f);
    ol.effectDistance = new Vector2(3f, -3f);

    var runeGo = new GameObject("RuneSeal", typeof(RectTransform), typeof(Image));
    runeGo.transform.SetParent(steleGo.transform, false);
    var rrt = runeGo.GetComponent<RectTransform>();
    rrt.anchoredPosition = new Vector2(0f, 30f);
